  "Mocking strategies in tests": [{ text: "Stubs return canned data, spies record calls on real functions, and mocks verify expected interactions", text_es: "Los stubs devuelven datos predefinidos, los spies registran las llamadas a funciones reales, y los mocks verifican las interacciones esperadas", is_correct: true }, { text: "Stubs, mocks and spies are all the same thing", text_es: "Stubs, mocks y spies son todos lo mismo", is_correct: false }, { text: "Mocks are only used in production code", text_es: "Los mocks solo se usan en código de producción", is_correct: false }],
  "TDD vs BDD": [{ text: "TDD writes a failing test first then the code (red-green-refactor); BDD describes behavior in business language (Given/When/Then)", text_es: "TDD escribe primero un test que falla y luego el código (red-green-refactor); BDD describe el comportamiento en lenguaje de negocio (Given/When/Then)", is_correct: true }, { text: "BDD means writing tests after the code is released", text_es: "BDD significa escribir los tests después de publicar el código", is_correct: false }, { text: "TDD is only for frontend and BDD only for backend", text_es: "TDD es solo para frontend y BDD solo para backend", is_correct: false }],
