  "Code splitting and lazy loading": [{ text: "Split the bundle with dynamic import() and React.lazy so code is loaded only when needed, reducing initial load", text_es: "Dividir el bundle con import() dinámico y React.lazy para que el código se cargue solo cuando hace falta, reduciendo la carga inicial", is_correct: true }, { text: "Merge all code into one file so the browser makes a single request", text_es: "Fusionar todo el código en un único archivo para que el navegador haga una sola petición", is_correct: false }, { text: "Delay the execution of every function by a few seconds", text_es: "Retrasar unos segundos la ejecución de cada función", is_correct: false }],
  "Critical rendering path": [{ text: "The steps from HTML/CSS/JS to pixels (DOM, CSSOM, render tree, layout, paint); optimize by reducing render-blocking resources", text_es: "Los pasos desde HTML/CSS/JS hasta los píxeles (DOM, CSSOM, render tree, layout, paint); se optimiza reduciendo los recursos que bloquean el renderizado", is_correct: true }, { text: "The path of the API requests made after the page has loaded", text_es: "El recorrido de las peticiones a la API que se hacen después de cargar la página", is_correct: false }, { text: "The order in which images are compressed on the server", text_es: "El orden en el que se comprimen las imágenes en el servidor", is_correct: false }],
  "Tree shaking and bundle analysis": [{ text: "Removing unused ES module exports at build time; analyze the bundle with tools like rollup-plugin-visualizer or webpack-bundle-analyzer", text_es: "Eliminar en tiempo de build los exports de módulos ES que no se usan; el bundle se analiza con herramientas como rollup-plugin-visualizer o webpack-bundle-analyzer", is_correct: true }, { text: "Deleting unused files from the node_modules folder by hand", text_es: "Borrar a mano los archivos que no se usan de la carpeta node_modules", is_correct: false }, { text: "Minifying CSS class names", text_es: "Minificar los nombres de las clases CSS", is_correct: false }],
