// Options for the batch 2 questions above.
const mockOptionsByTitleBatch2: Record<string, { text: string; text_es: string; is_correct: boolean }[]> = {
  "map, filter and reduce": [{ text: "map transforms each element into a new array of the same length; filter keeps elements matching a condition; reduce folds the array into a single accumulated value.", text_es: "map transforma cada elemento en un nuevo array de la misma longitud; filter conserva los elementos que cumplen una condición; reduce reduce el array a un único valor acumulado.", is_correct: true }, { text: "They are aliases for the same operation with different names.", text_es: "Son alias de la misma operación con nombres distintos.", is_correct: false }, { text: "map and filter mutate the original array, reduce does not.", text_es: "map y filter mutan el array original, reduce no.", is_correct: false }],
  "== vs ===": [{ text: "== compares values after type coercion, while === compares both value and type without coercion.", text_es: "== compara los valores después de la coerción de tipos, mientras que === compara valor y tipo sin coerción.", is_correct: true }, { text: "=== is only used for comparing objects, == for primitives.", text_es: "=== solo se usa para comparar objetos, == para primitivos.", is_correct: false }, { text: "There is no difference, they behave identically in modern JavaScript.", text_es: "No hay diferencia, se comportan igual en el JavaScript moderno.", is_correct: false }],
  "Hoisting": [{ text: "Variable and function declarations are moved to the top of their scope during compilation, so function declarations and var (as undefined) are usable before their line of code.", text_es: "Las declaraciones de variables y funciones se mueven al principio de su ámbito durante la compilación, de modo que las funciones declaradas y las var (como undefined) se pueden usar antes de su línea de código.", is_correct: true }, { text: "Hoisting means all variables are automatically made global.", text_es: "El hoisting significa que todas las variables se vuelven globales automáticamente.", is_correct: false }, { text: "Hoisting moves code execution to run after the event loop finishes.", text_es: "El hoisting hace que el código se ejecute después de que termine el event loop.", is_correct: false }],
  "The this keyword": [{ text: "It depends on how the function is called (call-site): as a method, this is the object; as a plain function call, this is undefined in strict mode or the global object otherwise; arrow functions inherit this lexically.", text_es: "Depende de cómo se llama a la función (call-site): como método, this es el objeto; como llamada a función normal, this es undefined en modo estricto o el objeto global en caso contrario; las funciones flecha heredan this léxicamente.", is_correct: true }, { text: "`this` always refers to the function itself.", text_es: "`this` siempre hace referencia a la propia función.", is_correct: false }, { text: "`this` is fixed at the moment the function is defined, regardless of how it's called.", text_es: "`this` queda fijado en el momento en que se define la función, sin importar cómo se llame.", is_correct: false }],
  "call, apply and bind": [{ text: "call and apply invoke the function immediately with a given this (call takes args individually, apply takes an array); bind returns a new function with this permanently set.", text_es: "call y apply invocan la función inmediatamente con un this dado (call recibe los argumentos por separado, apply los recibe como array); bind devuelve una nueva función con this fijado de forma permanente.", is_correct: true }, { text: "call and bind invoke immediately, apply returns a new function.", text_es: "call y bind invocan de inmediato, apply devuelve una nueva función.", is_correct: false }, { text: "They are all deprecated in favor of arrow functions.", text_es: "Los tres están obsoletos a favor de las funciones flecha.", is_correct: false }],
  "Debounce vs throttle": [{ text: "Debounce delays execution until a pause in calls has occurred; throttle limits execution to at most once per fixed time interval regardless of how often it's called.", text_es: "Debounce retrasa la ejecución hasta que se produce una pausa en las llamadas; throttle limita la ejecución a como mucho una vez por intervalo de tiempo fijo, sin importar cuántas veces se llame.", is_correct: true }, { text: "Throttle waits for a pause in calls; debounce runs at a fixed interval.", text_es: "Throttle espera a que haya una pausa en las llamadas; debounce se ejecuta a intervalos fijos.", is_correct: false }, { text: "They are two names for the same rate-limiting technique.", text_es: "Son dos nombres para la misma técnica de limitación de frecuencia.", is_correct: false }],
  "Shallow vs deep copy": [{ text: "A shallow copy duplicates only the top-level properties (nested objects are still shared by reference); a deep copy recursively duplicates every nested object too.", text_es: "Una copia superficial duplica solo las propiedades del primer nivel (los objetos anidados se siguen compartiendo por referencia); una copia profunda duplica recursivamente también cada objeto anidado.", is_correct: true }, { text: "A shallow copy is always faster but produces an invalid object.", text_es: "Una copia superficial siempre es más rápida pero produce un objeto inválido.", is_correct: false }, { text: "A deep copy only works on arrays, not plain objects.", text_es: "Una copia profunda solo funciona con arrays, no con objetos normales.", is_correct: false }],
  "WeakMap vs Map": [{ text: "WeakMap holds its keys weakly (object keys only), allowing garbage collection when there are no other references, and is not iterable; Map holds strong references and is iterable.", text_es: "WeakMap mantiene sus claves de forma débil (solo objetos como clave), permitiendo que se recolecten cuando no hay otras referencias, y no es iterable; Map mantiene referencias fuertes y sí es iterable.", is_correct: true }, { text: "WeakMap is just a slower version of Map with the same guarantees.", text_es: "WeakMap es solo una versión más lenta de Map con las mismas garantías.", is_correct: false }, { text: "WeakMap allows primitive keys while Map only allows object keys.", text_es: "WeakMap permite claves primitivas mientras que Map solo permite claves de tipo objeto.", is_correct: false }],
  "Optional chaining and nullish coalescing": [{ text: "?. (optional chaining) short-circuits to undefined when accessing a property on null/undefined instead of throwing; ?? (nullish coalescing) returns the right-hand value only when the left is null or undefined.", text_es: "?. (optional chaining) devuelve undefined en cortocircuito al acceder a una propiedad de null/undefined en lugar de lanzar un error; ?? (nullish coalescing) devuelve el valor de la derecha solo cuando el de la izquierda es null o undefined.", is_correct: true }, { text: "?. throws a custom error and ?? always returns the left-hand value.", text_es: "?. lanza un error personalizado y ?? siempre devuelve el valor de la izquierda.", is_correct: false }, { text: "Both operators are only available in TypeScript, not plain JavaScript.", text_es: "Ambos operadores solo están disponibles en TypeScript, no en JavaScript puro.", is_correct: false }],
  "Handling errors in async/await": [{ text: "Wrap the awaited call in a try/catch block, or attach .catch() to the returned promise, since a rejected awaited promise throws inside the async function.", text_es: "Envuelve la llamada con await en un bloque try/catch, o añade .catch() a la promise devuelta, ya que una promise esperada que se rechaza lanza una excepción dentro de la función async.", is_correct: true }, { text: "async/await cannot handle errors; you must always fall back to .then/.catch.", text_es: "async/await no puede manejar errores; siempre hay que recurrir a .then/.catch.", is_correct: false }, { text: "Errors in async functions are silently ignored unless you check a return code.", text_es: "Los errores en funciones async se ignoran silenciosamente a menos que compruebes un código de retorno.", is_correct: false }],
  "CommonJS vs ES Modules": [{ text: "CommonJS loads modules synchronously with require/module.exports (Node's original system); ES Modules use static import/export syntax, are statically analyzable, and support tree shaking.", text_es: "CommonJS carga los módulos de forma síncrona con require/module.exports (el sistema original de Node); los ES Modules usan la sintaxis estática import/export, son analizables estáticamente y admiten tree shaking.", is_correct: true }, { text: "CommonJS is the browser standard and ES Modules only work in Node.js.", text_es: "CommonJS es el estándar del navegador y los ES Modules solo funcionan en Node.js.", is_correct: false }, { text: "They are fully interchangeable with no differences in behavior.", text_es: "Son totalmente intercambiables y no tienen diferencias de comportamiento.", is_correct: false }],
  "Currying": [{ text: "Currying transforms a function taking multiple arguments into a sequence of functions each taking a single argument, enabling partial application and function composition.", text_es: "El currying transforma una función que recibe varios argumentos en una secuencia de funciones que reciben un único argumento cada una, lo que permite la aplicación parcial y la composición de funciones.", is_correct: true }, { text: "Currying is a way to make functions run in parallel.", text_es: "El currying es una forma de hacer que las funciones se ejecuten en paralelo.", is_correct: false }, { text: "Currying converts synchronous functions into asynchronous ones.", text_es: "El currying convierte funciones síncronas en asíncronas.", is_correct: false }],
  "any vs unknown": [{ text: "any disables type checking entirely; unknown also accepts any value but requires a type check or assertion before you can use it, preserving type safety.", text_es: "any desactiva por completo la comprobación de tipos; unknown también acepta cualquier valor pero exige una comprobación o aserción de tipo antes de poder usarlo, preservando la seguridad de tipos.", is_correct: true }, { text: "any and unknown are interchangeable aliases.", text_es: "any y unknown son alias intercambiables.", is_correct: false }, { text: "unknown can only be used for function return types.", text_es: "unknown solo se puede usar para tipos de retorno de funciones.", is_correct: false }],
  "Enums": [{ text: "Enums define a named set of related constant values (e.g. Direction.Up), improving readability over raw string/number literals scattered through the code.", text_es: "Los enums definen un conjunto con nombre de valores constantes relacionados (p. ej. Direction.Up), mejorando la legibilidad frente a literales de string/número sueltos por el código.", is_correct: true }, { text: "Enums are TypeScript's only way to define arrays with fixed length.", text_es: "Los enums son la única forma que tiene TypeScript de definir arrays de longitud fija.", is_correct: false }, { text: "Enums are compiled away and unusable at runtime.", text_es: "Los enums desaparecen al compilar y no se pueden usar en tiempo de ejecución.", is_correct: false }],
  "type vs interface": [{ text: "Both can describe object shapes; interfaces support declaration merging and are typically preferred for public object APIs, while type aliases can also represent unions, tuples, and primitives that interfaces cannot.", text_es: "Ambos pueden describir la forma de un objeto; las interfaces admiten declaration merging y suelen preferirse para APIs públicas de objetos, mientras que los alias de tipo también pueden representar uniones, tuplas y primitivos que las interfaces no pueden.", is_correct: true }, { text: "type can only describe primitives, interface only describes objects.", text_es: "type solo puede describir primitivos, interface solo describe objetos.", is_correct: false }, { text: "They are fully identical in every capability with no differences.", text_es: "Son totalmente idénticos en todas sus capacidades, sin diferencias.", is_correct: false }],
  "Union vs intersection types": [{ text: "A union type allows a value to be one of several types (A | B); an intersection type combines multiple types into one that must satisfy all of them (A & B).", text_es: "Un tipo unión permite que un valor sea uno de varios tipos (A | B); un tipo intersección combina varios tipos en uno que debe satisfacerlos todos (A & B).", is_correct: true }, { text: "Union requires all types to be satisfied; intersection allows any one of them.", text_es: "La unión exige que se cumplan todos los tipos; la intersección permite cualquiera de ellos.", is_correct: false }, { text: "Union and intersection only apply to primitive types, not objects.", text_es: "Unión e intersección solo se aplican a tipos primitivos, no a objetos.", is_correct: false }],
  "Type guards": [{ text: "A runtime check (like typeof, instanceof, or a custom predicate function returning `x is Type`) that narrows a variable's type within a conditional block.", text_es: "Una comprobación en tiempo de ejecución (como typeof, instanceof o una función predicado personalizada que devuelve `x is Type`) que acota el tipo de una variable dentro de un bloque condicional.", is_correct: true }, { text: "A compiler flag that disables type checking for a file.", text_es: "Una opción del compilador que desactiva la comprobación de tipos de un archivo.", is_correct: false }, { text: "A decorator that guards a class from being extended.", text_es: "Un decorador que impide que una clase pueda extenderse.", is_correct: false }],
  "Pick and Omit": [{ text: "Pick<T, K> creates a type with only the listed keys from T; Omit<T, K> creates a type with all keys of T except the listed ones.", text_es: "Pick<T, K> crea un tipo solo con las claves indicadas de T; Omit<T, K> crea un tipo con todas las claves de T excepto las indicadas.", is_correct: true }, { text: "Pick selects values at runtime; Omit deletes properties from the original object.", text_es: "Pick selecciona valores en tiempo de ejecución; Omit elimina propiedades del objeto original.", is_correct: false }, { text: "Both utility types only work on arrays, not object types.", text_es: "Ambos utility types solo funcionan con arrays, no con tipos objeto.", is_correct: false }],
  "Discriminated unions": [{ text: "A union of object types that share a common literal 'tag' property (e.g. kind: 'circle' | 'square'), letting TypeScript narrow the exact shape based on that tag in a switch or if.", text_es: "Una unión de tipos objeto que comparten una propiedad literal común a modo de 'etiqueta' (p. ej. kind: 'circle' | 'square'), que permite a TypeScript acotar la forma exacta según esa etiqueta en un switch o if.", is_correct: true }, { text: "A union type that TypeScript refuses to compile because it's ambiguous.", text_es: "Un tipo unión que TypeScript se niega a compilar por ser ambiguo.", is_correct: false }, { text: "An enum where every member must have a unique numeric value.", text_es: "Un enum en el que cada miembro debe tener un valor numérico único.", is_correct: false }],
  "Declaration merging": [{ text: "TypeScript's ability to combine multiple declarations with the same name (e.g. two `interface Foo` blocks) into a single merged definition, commonly used to extend third-party types.", text_es: "La capacidad de TypeScript de combinar varias declaraciones con el mismo nombre (p. ej. dos bloques `interface Foo`) en una única definición fusionada, usada habitualmente para ampliar tipos de terceros.", is_correct: true }, { text: "A build step that merges every .ts file in the project into one bundle.", text_es: "Un paso del build que fusiona todos los archivos .ts del proyecto en un único bundle.", is_correct: false }, { text: "A runtime feature that merges two objects deeply.", text_es: "Una funcionalidad en tiempo de ejecución que fusiona dos objetos en profundidad.", is_correct: false }],
  "Non-null assertion operator": [{ text: "It tells the compiler to treat a value as non-null/non-undefined, suppressing the type error without any runtime check — it's purely a compile-time assertion.", text_es: "Le indica al compilador que trate un valor como no nulo/no undefined, suprimiendo el error de tipo sin ninguna comprobación en tiempo de ejecución: es una aserción puramente de compilación.", is_correct: true }, { text: "It throws a runtime error if the value is null or undefined.", text_es: "Lanza un error en tiempo de ejecución si el valor es null o undefined.", is_correct: false }, { text: "It converts the value to a boolean, negating it.", text_es: "Convierte el valor a booleano, negándolo.", is_correct: false }],
  "The satisfies operator": [{ text: "It checks that an expression matches a given type without widening or changing the expression's inferred type, unlike a type annotation which would widen it.", text_es: "Comprueba que una expresión cumple un tipo dado sin ampliar ni cambiar el tipo inferido de la expresión, a diferencia de una anotación de tipo que sí lo ampliaría.", is_correct: true }, { text: "It replaces `as` for all type assertions and behaves identically.", text_es: "Sustituye a `as` para todas las aserciones de tipo y se comporta igual.", is_correct: false }, { text: "It runs a runtime validation against a JSON schema.", text_es: "Ejecuta una validación en tiempo de ejecución contra un JSON schema.", is_correct: false }],
  "Template literal types": [{ text: "Types built using template string syntax (e.g. type Event = `on${Capitalize<string>}`) that combine string literal types to generate new, precise string types.", text_es: "Tipos construidos con la sintaxis de plantillas de cadena (p. ej. type Event = `on${Capitalize<string>}`) que combinan tipos literales de cadena para generar nuevos tipos de cadena precisos.", is_correct: true }, { text: "A way to embed TypeScript code inside template literal strings at runtime.", text_es: "Una forma de incrustar código TypeScript dentro de plantillas de cadena en tiempo de ejecución.", is_correct: false }, { text: "A syntax for writing multi-line comments in type declarations.", text_es: "Una sintaxis para escribir comentarios multilínea en las declaraciones de tipo.", is_correct: false }],
  "Function overloads": [{ text: "Multiple type signatures declared for the same function name, letting callers see different valid parameter/return combinations while a single implementation handles them all.", text_es: "Varias firmas de tipo declaradas para el mismo nombre de función, que permiten a quien la llama ver distintas combinaciones válidas de parámetros/retorno, mientras una única implementación las gestiona todas.", is_correct: true }, { text: "Overloads let you define multiple functions with the same name and different runtime behavior automatically dispatched.", text_es: "Las sobrecargas permiten definir varias funciones con el mismo nombre y comportamiento en tiempo de ejecución distinto, despachadas automáticamente.", is_correct: false }, { text: "Overloads are only allowed on class constructors, not standalone functions.", text_es: "Las sobrecargas solo están permitidas en constructores de clase, no en funciones sueltas.", is_correct: false }],
  "Ambient declarations (.d.ts)": [{ text: "It describes the shape of existing JavaScript code (types, functions, modules) without providing implementations, so TypeScript can type-check code that uses plain JS or third-party libraries.", text_es: "Describe la forma de código JavaScript ya existente (tipos, funciones, módulos) sin aportar implementaciones, de modo que TypeScript pueda comprobar tipos en código que usa JS puro o librerías de terceros.", is_correct: true }, { text: ".d.ts files contain the compiled JavaScript output of a TypeScript project.", text_es: "Los archivos .d.ts contienen el JavaScript compilado de salida de un proyecto TypeScript.", is_correct: false }, { text: "They are required to run TypeScript code in Node.js.", text_es: "Son necesarios para ejecutar código TypeScript en Node.js.", is_correct: false }],
  "strictNullChecks": [{ text: "It makes null and undefined distinct types that must be explicitly included in a type's definition, preventing accidental null/undefined access errors that are otherwise silently allowed.", text_es: "Convierte null y undefined en tipos distintos que deben incluirse explícitamente en la definición de un tipo, evitando errores accidentales de acceso a null/undefined que de otro modo se permitirían en silencio.", is_correct: true }, { text: "It removes all null and undefined values from objects at compile time.", text_es: "Elimina todos los valores null y undefined de los objetos en tiempo de compilación.", is_correct: false }, { text: "It disables the use of the null keyword anywhere in the codebase.", text_es: "Desactiva el uso de la palabra clave null en cualquier parte del código.", is_correct: false }],
  "Controlled vs uncontrolled components": [{ text: "A controlled component's value is driven by React state (via value + onChange); an uncontrolled component keeps its own internal DOM state, accessed via a ref when needed.", text_es: "El valor de un componente controlado viene dado por el estado de React (mediante value + onChange); uno no controlado mantiene su propio estado interno en el DOM, accesible mediante una ref cuando hace falta.", is_correct: true }, { text: "Controlled components can only be used with class components.", text_es: "Los componentes controlados solo se pueden usar con componentes de clase.", is_correct: false }, { text: "Uncontrolled components cannot have a default value.", text_es: "Los componentes no controlados no pueden tener un valor por defecto.", is_correct: false }],
  "Lifting state up": [{ text: "Moving shared state to the closest common ancestor of the components that need it, then passing it down via props, so multiple components stay in sync.", text_es: "Mover el estado compartido al ancestro común más cercano de los componentes que lo necesitan, y luego pasarlo hacia abajo mediante props, para que varios componentes se mantengan sincronizados.", is_correct: true }, { text: "Moving all component state into a global Redux store.", text_es: "Mover todo el estado de los componentes a un store global de Redux.", is_correct: false }, { text: "Converting a function component into a class component.", text_es: "Convertir un componente función en un componente de clase.", is_correct: false }],
  "Context API": [{ text: "It lets you share data (like theme or auth state) across a component tree without manually passing props down through every intermediate level (prop drilling).", text_es: "Permite compartir datos (como el tema o el estado de autenticación) por todo un árbol de componentes sin pasar props manualmente por cada nivel intermedio (prop drilling).", is_correct: true }, { text: "It replaces useState entirely for all local component state.", text_es: "Sustituye por completo a useState para todo el estado local de un componente.", is_correct: false }, { text: "It is used only for fetching data from a REST API.", text_es: "Solo se usa para obtener datos de una API REST.", is_correct: false }],
  "useEffect cleanup function": [{ text: "It runs before the effect re-runs and when the component unmounts, letting you cancel subscriptions, timers, or event listeners set up by the effect to avoid leaks.", text_es: "Se ejecuta antes de que el efecto se vuelva a ejecutar y cuando el componente se desmonta, permitiendo cancelar suscripciones, temporizadores o listeners de eventos creados por el efecto para evitar fugas.", is_correct: true }, { text: "It clears all component state back to its initial values.", text_es: "Restablece todo el estado del componente a sus valores iniciales.", is_correct: false }, { text: "It deletes the component from the DOM immediately.", text_es: "Elimina el componente del DOM de inmediato.", is_correct: false }],
  "useRef use cases": [{ text: "Accessing a DOM node directly (e.g. focusing an input), and storing a mutable value that persists across renders without triggering a re-render when it changes.", text_es: "Acceder directamente a un nodo del DOM (p. ej. para enfocar un input), y guardar un valor mutable que persiste entre renders sin provocar un nuevo render al cambiar.", is_correct: true }, { text: "useRef is only for storing state that should trigger re-renders, like useState.", text_es: "useRef solo sirve para guardar estado que debería provocar re-renders, como useState.", is_correct: false }, { text: "useRef can only be used inside class components.", text_es: "useRef solo se puede usar dentro de componentes de clase.", is_correct: false }],
  "Portals": [{ text: "ReactDOM.createPortal renders a child into a DOM node outside its parent's DOM hierarchy while keeping it in the same React component tree — useful for modals, tooltips, and dropdowns that must escape overflow/z-index constraints.", text_es: "ReactDOM.createPortal renderiza un hijo en un nodo del DOM fuera de la jerarquía del DOM de su padre, manteniéndolo en el mismo árbol de componentes de React; útil para modales, tooltips y desplegables que deben escapar de restricciones de overflow/z-index.", is_correct: true }, { text: "A Portal is a special hook for fetching data across routes.", text_es: "Un Portal es un hook especial para obtener datos entre rutas.", is_correct: false }, { text: "A Portal lets one React app render components from a completely different app.", text_es: "Un Portal permite que una app de React renderice componentes de otra app completamente distinta.", is_correct: false }],
  "Suspense": [{ text: "It lets a component 'wait' for something (like a lazy-loaded chunk or, with supporting data libraries, a data fetch) before rendering, showing a fallback UI in the meantime.", text_es: "Permite que un componente 'espere' a algo (como un chunk cargado de forma diferida o, con librerías de datos compatibles, una petición de datos) antes de renderizar, mostrando mientras tanto una interfaz alternativa.", is_correct: true }, { text: "Suspense pauses the entire JavaScript engine until data arrives.", text_es: "Suspense pausa todo el motor de JavaScript hasta que llegan los datos.", is_correct: false }, { text: "Suspense is a testing utility for mocking API calls.", text_es: "Suspense es una utilidad de testing para simular llamadas a una API.", is_correct: false }],
  "Rules of hooks": [{ text: "Hooks must be called at the top level (never inside loops/conditions/nested functions) and only from React functions, because React relies on the consistent call order across renders to associate state with the right hook.", text_es: "Los hooks deben llamarse en el nivel superior (nunca dentro de bucles/condicionales/funciones anidadas) y solo desde funciones de React, porque React depende de que el orden de llamada sea consistente entre renders para asociar el estado con el hook correcto.", is_correct: true }, { text: "Hooks can be called conditionally as long as the condition never changes.", text_es: "Los hooks se pueden llamar de forma condicional siempre que la condición nunca cambie.", is_correct: false }, { text: "The rules of hooks only apply to useState, not other hooks.", text_es: "Las reglas de los hooks solo se aplican a useState, no a los demás hooks.", is_correct: false }],
  "Why keys matter in lists": [{ text: "Keys let React's reconciliation algorithm identify which items changed, were added, or were removed between renders, instead of re-rendering the whole list or misapplying state to the wrong item.", text_es: "Las keys permiten que el algoritmo de reconciliación de React identifique qué elementos cambiaron, se añadieron o se eliminaron entre renders, en lugar de volver a renderizar toda la lista o aplicar mal el estado a un elemento equivocado.", is_correct: true }, { text: "Keys are only used for styling list items with CSS.", text_es: "Las keys solo se usan para dar estilo con CSS a los elementos de una lista.", is_correct: false }, { text: "Keys are optional and have no effect on rendering performance or correctness.", text_es: "Las keys son opcionales y no afectan al rendimiento ni a la corrección del renderizado.", is_correct: false }],
  "Prop drilling": [{ text: "Passing props through many intermediate components that don't need them just to reach a deeply nested child, which makes components harder to refactor and reuse.", text_es: "Pasar props a través de muchos componentes intermedios que no las necesitan, solo para llegar a un hijo profundamente anidado, lo que dificulta refactorizar y reutilizar los componentes.", is_correct: true }, { text: "A performance optimization technique used to avoid unnecessary re-renders.", text_es: "Una técnica de optimización de rendimiento usada para evitar re-renders innecesarios.", is_correct: false }, { text: "A pattern for validating props with PropTypes at every level.", text_es: "Un patrón para validar props con PropTypes en cada nivel.", is_correct: false }],
  "StrictMode double effects": [{ text: "To help surface side effects that aren't properly cleaned up, by intentionally re-running them once to check they behave correctly when mounted, unmounted, and remounted — it only happens in development, not production.", text_es: "Para ayudar a detectar efectos secundarios que no se limpian correctamente, volviéndolos a ejecutar a propósito una vez para comprobar que se comportan bien al montar, desmontar y volver a montar; solo ocurre en desarrollo, no en producción.", is_correct: true }, { text: "It's a bug in React that will be fixed in a future release.", text_es: "Es un fallo de React que se corregirá en una futura versión.", is_correct: false }, { text: "It doubles rendering performance by running effects in parallel.", text_es: "Duplica el rendimiento del renderizado ejecutando los efectos en paralelo.", is_correct: false }],
  "require vs import": [{ text: "require is CommonJS, resolved synchronously at runtime; import is the ES Modules syntax, statically analyzed and resolved before execution, enabling tree shaking and top-level await.", text_es: "require es CommonJS y se resuelve de forma síncrona en tiempo de ejecución; import es la sintaxis de ES Modules, se analiza estáticamente y se resuelve antes de la ejecución, lo que permite tree shaking y top-level await.", is_correct: true }, { text: "They are identical keywords that Node treats the same way internally.", text_es: "Son palabras clave idénticas que Node trata igual internamente.", is_correct: false }, { text: "require only works in the browser, import only works in Node.js.", text_es: "require solo funciona en el navegador, import solo funciona en Node.js.", is_correct: false }],
  "CommonJS module caching": [{ text: "No — Node caches the exported module object by resolved file path after the first require(), so subsequent requires return the same cached instance instead of re-running the module code.", text_es: "No: Node cachea el objeto exportado del módulo según la ruta de archivo resuelta tras el primer require(), así que los siguientes require devuelven la misma instancia en caché en lugar de volver a ejecutar el código del módulo.", is_correct: true }, { text: "Yes, every call to require() re-executes the entire module from scratch.", text_es: "Sí, cada llamada a require() vuelve a ejecutar el módulo entero desde cero.", is_correct: false }, { text: "Only modules inside node_modules are cached; local files are always re-executed.", text_es: "Solo se cachean los módulos dentro de node_modules; los archivos locales siempre se vuelven a ejecutar.", is_correct: false }],
  "Environment variables and dotenv": [{ text: "Values are read from process.env, often loaded from a local .env file via a package like dotenv during development, while production sets real environment variables through the hosting platform.", text_es: "Los valores se leen de process.env, a menudo cargados desde un archivo .env local mediante un paquete como dotenv durante el desarrollo, mientras que en producción las variables de entorno reales las define la plataforma de hosting.", is_correct: true }, { text: "Environment variables must be hardcoded directly into the source code.", text_es: "Las variables de entorno deben escribirse directamente en el código fuente.", is_correct: false }, { text: "Node.js has no concept of environment variables; only command-line arguments work.", text_es: "Node.js no tiene el concepto de variables de entorno; solo funcionan los argumentos de línea de comandos.", is_correct: false }],
  "Error-first callbacks": [{ text: "A callback's first parameter is reserved for an error (or null if none occurred), and subsequent parameters carry the result — the standard pattern before Promises became common.", text_es: "El primer parámetro de un callback se reserva para un error (o null si no hubo ninguno), y los siguientes parámetros llevan el resultado; el patrón estándar antes de que las Promises se popularizaran.", is_correct: true }, { text: "It means the callback function must be defined before any other code in the file.", text_es: "Significa que la función callback debe definirse antes que cualquier otro código del archivo.", is_correct: false }, { text: "It's a convention where errors are thrown instead of passed as arguments.", text_es: "Es una convención en la que los errores se lanzan en lugar de pasarse como argumentos.", is_correct: false }],
  "child_process module": [{ text: "It lets Node spawn and communicate with OS-level subprocesses (via spawn, exec, fork, execFile) — useful for running shell commands or CPU-heavy scripts outside the main event loop.", text_es: "Permite a Node lanzar y comunicarse con subprocesos del sistema operativo (mediante spawn, exec, fork, execFile), útil para ejecutar comandos de shell o scripts intensivos de CPU fuera del event loop principal.", is_correct: true }, { text: "It creates additional V8 isolates that share the same memory as the parent.", text_es: "Crea isolates de V8 adicionales que comparten la misma memoria que el proceso padre.", is_correct: false }, { text: "It's used exclusively for spawning new HTTP servers.", text_es: "Se usa exclusivamente para lanzar nuevos servidores HTTP.", is_correct: false }],
  "Buffer class": [{ text: "It represents a fixed-length chunk of raw binary data in memory, used for handling things like file I/O, network protocols, and streams before Node.js supported TypedArrays natively.", text_es: "Representa un bloque de longitud fija de datos binarios en memoria, usado para cosas como I/O de archivos, protocolos de red y streams, desde antes de que Node.js soportara TypedArrays de forma nativa.", is_correct: true }, { text: "Buffer is a queue data structure used to throttle incoming HTTP requests.", text_es: "Buffer es una estructura de datos tipo cola usada para limitar la frecuencia de las peticiones HTTP entrantes.", is_correct: false }, { text: "Buffer stores only UTF-8 text and cannot hold binary data.", text_es: "Buffer solo almacena texto UTF-8 y no puede contener datos binarios.", is_correct: false }],
  "fs sync vs async": [{ text: "readFileSync blocks the event loop until the file is fully read; readFile is asynchronous and uses a callback (or Promise via fs/promises), letting other work proceed while I/O happens.", text_es: "readFileSync bloquea el event loop hasta que el archivo se lee por completo; readFile es asíncrono y usa un callback (o Promise vía fs/promises), permitiendo que otro trabajo avance mientras ocurre la I/O.", is_correct: true }, { text: "readFileSync is faster in every scenario because it skips the event loop.", text_es: "readFileSync es más rápido en todos los casos porque se salta el event loop.", is_correct: false }, { text: "readFile can only read files smaller than 1MB.", text_es: "readFile solo puede leer archivos de menos de 1MB.", is_correct: false }],
  "Express error-handling middleware": [{ text: "Define a middleware function with four parameters (err, req, res, next) placed after your routes; Express recognizes the arity and routes errors passed to next(err) there.", text_es: "Definiendo una función middleware con cuatro parámetros (err, req, res, next) colocada después de tus rutas; Express reconoce esa cantidad de parámetros y envía ahí los errores pasados a next(err).", is_correct: true }, { text: "Wrap the entire app.listen() call in a single global try/catch block.", text_es: "Envolviendo toda la llamada a app.listen() en un único bloque try/catch global.", is_correct: false }, { text: "Error handling in Express requires a separate error-handling server.", text_es: "El manejo de errores en Express requiere un servidor de errores independiente.", is_correct: false }],
  "Rate limiting middleware": [{ text: "Track request counts per client (e.g. by IP or API key) within a time window, using middleware (like express-rate-limit or a Redis-backed counter) that rejects requests once the limit is exceeded.", text_es: "Llevando la cuenta de peticiones por cliente (p. ej. por IP o API key) dentro de una ventana de tiempo, mediante un middleware (como express-rate-limit o un contador respaldado por Redis) que rechaza las peticiones al superar el límite.", is_correct: true }, { text: "Rate limiting must be implemented at the database level, never in application code.", text_es: "El rate limiting debe implementarse a nivel de base de datos, nunca en el código de la aplicación.", is_correct: false }, { text: "Node.js automatically rate-limits all incoming HTTP requests by default.", text_es: "Node.js limita automáticamente todas las peticiones HTTP entrantes por defecto.", is_correct: false }],
  "npm vs npx": [{ text: "npm installs and manages packages; npx executes a package's binary directly (installing it temporarily if not already present) without adding it as a project dependency.", text_es: "npm instala y gestiona paquetes; npx ejecuta directamente el binario de un paquete (instalándolo temporalmente si no está ya presente) sin añadirlo como dependencia del proyecto.", is_correct: true }, { text: "npx is only used to publish packages, never to run them.", text_es: "npx solo se usa para publicar paquetes, nunca para ejecutarlos.", is_correct: false }, { text: "npm and npx are two names for the exact same command.", text_es: "npm y npx son dos nombres para exactamente el mismo comando.", is_correct: false }],
  "package-lock.json purpose": [{ text: "It records the exact resolved version of every installed dependency (and sub-dependency), ensuring everyone who installs the project gets identical dependency trees.", text_es: "Registra la versión exacta resuelta de cada dependencia instalada (y subdependencia), garantizando que todo el que instale el proyecto obtenga árboles de dependencias idénticos.", is_correct: true }, { text: "It stores the compiled JavaScript output of the project.", text_es: "Almacena el JavaScript compilado de salida del proyecto.", is_correct: false }, { text: "It lists which packages are explicitly forbidden from being installed.", text_es: "Lista qué paquetes están explícitamente prohibidos de instalar.", is_correct: false }],
  "Health check endpoints": [{ text: "So load balancers, orchestrators (like Kubernetes), and monitoring tools can automatically verify the service is running and ready to accept traffic.", text_es: "Para que los balanceadores de carga, orquestadores (como Kubernetes) y herramientas de monitorización puedan verificar automáticamente que el servicio está en marcha y listo para recibir tráfico.", is_correct: true }, { text: "It's required by the HTTP specification for every server.", text_es: "Lo exige la especificación HTTP para todo servidor.", is_correct: false }, { text: "It's used only to display the server's uptime to end users in the UI.", text_es: "Solo se usa para mostrar el uptime del servidor a los usuarios finales en la interfaz.", is_correct: false }],
  "Debugging with --inspect": [{ text: "Start Node with the --inspect (or --inspect-brk to pause on the first line) flag, which opens a debugging port that Chrome DevTools (via chrome://inspect) or an IDE can attach to.", text_es: "Arrancando Node con el flag --inspect (o --inspect-brk para pausar en la primera línea), que abre un puerto de depuración al que Chrome DevTools (vía chrome://inspect) o un IDE pueden conectarse.", is_correct: true }, { text: "Node.js processes can only be debugged using console.log statements.", text_es: "Los procesos Node.js solo se pueden depurar usando sentencias console.log.", is_correct: false }, { text: "You must recompile Node.js from source with debug symbols enabled.", text_es: "Hay que recompilar Node.js desde el código fuente con los símbolos de depuración activados.", is_correct: false }],
  "Primary key vs unique constraint": [{ text: "A PRIMARY KEY uniquely identifies each row, disallows NULLs, and a table can have only one; a UNIQUE constraint also enforces distinct values but allows NULLs (per most databases) and a table can have several.", text_es: "Una PRIMARY KEY identifica de forma única cada fila, no permite NULL y una tabla solo puede tener una; una restricción UNIQUE también exige valores distintos pero permite NULL (según la mayoría de bases de datos) y una tabla puede tener varias.", is_correct: true }, { text: "A table can have multiple primary keys but only one unique constraint.", text_es: "Una tabla puede tener varias claves primarias pero solo una restricción unique.", is_correct: false }, { text: "UNIQUE constraints are enforced only at the application level, not the database.", text_es: "Las restricciones UNIQUE solo se aplican a nivel de aplicación, no de base de datos.", is_correct: false }],
  "Foreign keys": [{ text: "It enforces referential integrity by requiring a column's values to match values in a referenced table's primary/unique key, preventing orphaned or invalid references.", text_es: "Garantiza la integridad referencial exigiendo que los valores de una columna coincidan con valores de la clave primaria/unique de una tabla referenciada, evitando referencias huérfanas o inválidas.", is_correct: true }, { text: "It automatically creates an index but enforces no validation rules.", text_es: "Crea automáticamente un índice pero no aplica ninguna regla de validación.", is_correct: false }, { text: "It duplicates the referenced table's data into the current table.", text_es: "Duplica los datos de la tabla referenciada en la tabla actual.", is_correct: false }],
  "GROUP BY basics": [{ text: "It groups rows sharing the same values in specified columns into summary rows, typically used together with aggregate functions like COUNT, SUM, or AVG.", text_es: "Agrupa las filas que comparten los mismos valores en unas columnas indicadas en filas resumen, normalmente usada junto con funciones de agregación como COUNT, SUM o AVG.", is_correct: true }, { text: "It sorts rows alphabetically by the specified column.", text_es: "Ordena las filas alfabéticamente por la columna indicada.", is_correct: false }, { text: "It removes duplicate rows from the result set entirely.", text_es: "Elimina por completo las filas duplicadas del resultado.", is_correct: false }],
  "Subquery vs JOIN performance": [{ text: "A correlated subquery that re-executes for every outer row can be much slower than a JOIN, which the query planner can often optimize with a single pass and proper index usage.", text_es: "Una subconsulta correlacionada que se vuelve a ejecutar por cada fila externa puede ser mucho más lenta que un JOIN, que el planificador de consultas suele poder optimizar en una sola pasada usando índices adecuados.", is_correct: true }, { text: "Subqueries are always faster than JOINs in every database engine.", text_es: "Las subconsultas siempre son más rápidas que los JOIN en cualquier motor de base de datos.", is_correct: false }, { text: "JOINs cannot be used with WHERE clauses, only subqueries can.", text_es: "Los JOIN no se pueden usar con cláusulas WHERE, solo las subconsultas pueden.", is_correct: false }],
  "UNION vs UNION ALL": [{ text: "UNION combines result sets and removes duplicate rows (requiring an extra sort/dedup step); UNION ALL combines them and keeps duplicates, which is faster since no dedup is needed.", text_es: "UNION combina los resultados y elimina las filas duplicadas (lo que exige un paso extra de ordenación/deduplicación); UNION ALL los combina conservando los duplicados, lo que es más rápido al no necesitar deduplicar.", is_correct: true }, { text: "UNION ALL requires both queries to return the same number of duplicate rows.", text_es: "UNION ALL exige que ambas consultas devuelvan el mismo número de filas duplicadas.", is_correct: false }, { text: "UNION can combine columns from unrelated queries with different column counts.", text_es: "UNION puede combinar columnas de consultas no relacionadas con distinto número de columnas.", is_correct: false }],
  "Self join": [{ text: "A join where a table is joined with itself (using aliases), useful for comparing rows within the same table — e.g. finding employees and their managers stored in the same employees table.", text_es: "Un join en el que una tabla se une consigo misma (usando alias), útil para comparar filas dentro de la misma tabla, por ejemplo para relacionar empleados con sus jefes guardados en la misma tabla employees.", is_correct: true }, { text: "A join that only works when a table has exactly one column.", text_es: "Un join que solo funciona cuando una tabla tiene exactamente una columna.", is_correct: false }, { text: "A special join type that automatically merges duplicate tables in a database.", text_es: "Un tipo especial de join que fusiona automáticamente tablas duplicadas de una base de datos.", is_correct: false }],
  "NULL handling": [{ text: "NULL represents an unknown value, so any comparison with = against NULL evaluates to unknown (not true), never matching — you must use IS NULL / IS NOT NULL instead.", text_es: "NULL representa un valor desconocido, así que cualquier comparación con = frente a NULL se evalúa como desconocido (no true) y nunca coincide; hay que usar IS NULL / IS NOT NULL en su lugar.", is_correct: true }, { text: "Because NULL is treated as the empty string, not as unknown.", text_es: "Porque NULL se trata como la cadena vacía, no como desconocido.", is_correct: false }, { text: "It's a syntax error in standard SQL and the query would fail to run.", text_es: "Es un error de sintaxis en SQL estándar y la consulta fallaría al ejecutarse.", is_correct: false }],
  "Window functions": [{ text: "They perform a calculation across a set of rows related to the current row (a 'window', defined with OVER/PARTITION BY) without collapsing the result into a single grouped row, unlike GROUP BY.", text_es: "Realizan un cálculo sobre un conjunto de filas relacionadas con la fila actual (una 'ventana', definida con OVER/PARTITION BY) sin reducir el resultado a una única fila agrupada, a diferencia de GROUP BY.", is_correct: true }, { text: "Window functions permanently reorder the physical rows in a table.", text_es: "Las funciones de ventana reordenan de forma permanente las filas físicas de una tabla.", is_correct: false }, { text: "Window functions can only be used with the GROUP BY clause, never alone.", text_es: "Las funciones de ventana solo se pueden usar junto con GROUP BY, nunca solas.", is_correct: false }],
  "UPSERT / ON CONFLICT": [{ text: "It attempts to insert a row, and if it violates a uniqueness constraint, updates the existing conflicting row instead, in a single atomic statement.", text_es: "Intenta insertar una fila y, si viola una restricción de unicidad, actualiza en su lugar la fila existente en conflicto, todo en una única sentencia atómica.", is_correct: true }, { text: "It inserts a row and always fails if any constraint would be violated.", text_es: "Inserta una fila y siempre falla si se fuera a violar alguna restricción.", is_correct: false }, { text: "It deletes the conflicting row and skips the insert entirely.", text_es: "Elimina la fila en conflicto y se salta por completo la inserción.", is_correct: false }],
  "Database migrations": [{ text: "A migration is an incremental, scripted change to the database schema (create table, add column, etc.); version-controlling them lets a team apply schema changes consistently and roll them back if needed.", text_es: "Una migración es un cambio incremental y con script sobre el esquema de la base de datos (crear tabla, añadir columna, etc.); versionarlas permite a un equipo aplicar cambios de esquema de forma consistente y revertirlos si hace falta.", is_correct: true }, { text: "A migration means physically moving a database server to new hardware.", text_es: "Una migración significa mover físicamente un servidor de base de datos a hardware nuevo.", is_correct: false }, { text: "Migrations are only used for moving data between different database vendors.", text_es: "Las migraciones solo se usan para mover datos entre distintos proveedores de base de datos.", is_correct: false }],
  "N+1 query problem": [{ text: "It happens when fetching a list of N items triggers one additional query per item to fetch related data (N extra queries); it's avoided with a JOIN, a batched IN query, or eager loading.", text_es: "Ocurre cuando obtener una lista de N elementos dispara una consulta adicional por elemento para traer datos relacionados (N consultas extra); se evita con un JOIN, una consulta IN en lote, o eager loading.", is_correct: true }, { text: "It refers to running exactly N+1 identical queries in a transaction for safety.", text_es: "Se refiere a ejecutar exactamente N+1 consultas idénticas en una transacción por seguridad.", is_correct: false }, { text: "It's a PostgreSQL-specific error that only occurs with more than 1 index.", text_es: "Es un error específico de PostgreSQL que solo ocurre con más de 1 índice.", is_correct: false }],
  "Composite indexes": [{ text: "An index built on multiple columns together; the database can use it efficiently for queries filtering on a leading prefix of those columns (in order), but not efficiently if only a later column is filtered.", text_es: "Un índice construido sobre varias columnas a la vez; la base de datos puede usarlo eficientemente en consultas que filtran por un prefijo inicial de esas columnas (en orden), pero no de forma eficiente si solo se filtra por una columna posterior.", is_correct: true }, { text: "Column order in a composite index has no effect on which queries can use it.", text_es: "El orden de las columnas en un índice compuesto no afecta a qué consultas pueden usarlo.", is_correct: false }, { text: "A composite index can only ever contain exactly two columns.", text_es: "Un índice compuesto solo puede contener exactamente dos columnas.", is_correct: false }],
  "What is a Dockerfile": [{ text: "A text file with a sequence of instructions (FROM, COPY, RUN, CMD, etc.) that Docker reads to build a reproducible image.", text_es: "Un archivo de texto con una secuencia de instrucciones (FROM, COPY, RUN, CMD, etc.) que Docker lee para construir una imagen reproducible.", is_correct: true }, { text: "A configuration file that only lists environment variables for a container.", text_es: "Un archivo de configuración que solo lista variables de entorno para un contenedor.", is_correct: false }, { text: "A compiled binary that runs containers directly without an image.", text_es: "Un binario compilado que ejecuta contenedores directamente sin necesidad de imagen.", is_correct: false }],
  "CMD vs ENTRYPOINT": [{ text: "ENTRYPOINT sets the fixed executable a container always runs; CMD supplies default arguments to it (or the whole command if ENTRYPOINT isn't set) that can be overridden at `docker run` time.", text_es: "ENTRYPOINT fija el ejecutable que el contenedor siempre ejecuta; CMD le proporciona argumentos por defecto (o el comando completo si no hay ENTRYPOINT) que se pueden sobrescribir al hacer `docker run`.", is_correct: true }, { text: "CMD and ENTRYPOINT are interchangeable keywords with identical behavior.", text_es: "CMD y ENTRYPOINT son palabras clave intercambiables con el mismo comportamiento.", is_correct: false }, { text: "ENTRYPOINT can only be used in the base image, never in a derived one.", text_es: "ENTRYPOINT solo se puede usar en la imagen base, nunca en una derivada.", is_correct: false }],
  ".dockerignore purpose": [{ text: "It excludes specified files and directories (like node_modules or .git) from the build context sent to the Docker daemon, speeding up builds and keeping images smaller.", text_es: "Excluye los archivos y directorios indicados (como node_modules o .git) del contexto de build que se envía al daemon de Docker, acelerando los builds y manteniendo las imágenes más pequeñas.", is_correct: true }, { text: "It lists which Docker commands are forbidden inside the Dockerfile.", text_es: "Lista qué comandos de Docker están prohibidos dentro del Dockerfile.", is_correct: false }, { text: "It tells Docker which containers should never be stopped.", text_es: "Le indica a Docker qué contenedores nunca deben detenerse.", is_correct: false }],
  "Image layers and caching": [{ text: "Each Dockerfile instruction creates a cached layer; if an instruction and its inputs haven't changed since the last build, Docker reuses the cached layer instead of re-executing it, speeding up rebuilds.", text_es: "Cada instrucción del Dockerfile crea una capa en caché; si una instrucción y sus entradas no han cambiado desde el último build, Docker reutiliza la capa en caché en lugar de volver a ejecutarla, acelerando las reconstrucciones.", is_correct: true }, { text: "Every build always re-executes every instruction from scratch with no caching.", text_es: "Cada build siempre vuelve a ejecutar todas las instrucciones desde cero, sin caché.", is_correct: false }, { text: "Layers are merged into a single file before any caching can occur.", text_es: "Las capas se fusionan en un único archivo antes de que pueda haber caché.", is_correct: false }],
  "docker-compose purpose": [{ text: "It lets you define and run a multi-container application (services, networks, volumes) from a single YAML file with one command, instead of manually running many `docker run` commands.", text_es: "Permite definir y ejecutar una aplicación multi-contenedor (servicios, redes, volúmenes) desde un único archivo YAML con un solo comando, en lugar de ejecutar manualmente muchos comandos `docker run`.", is_correct: true }, { text: "It replaces Dockerfiles entirely; images are no longer needed.", text_es: "Sustituye por completo a los Dockerfiles; ya no hacen falta imágenes.", is_correct: false }, { text: "It's a tool exclusively for pushing images to Docker Hub.", text_es: "Es una herramienta exclusiva para subir imágenes a Docker Hub.", is_correct: false }],
  "Environment variables in containers": [{ text: "With the -e flag or --env-file on `docker run`, or the environment/env_file keys in docker-compose.yml, which set process.env-style variables inside the container.", text_es: "Con el flag -e o --env-file en `docker run`, o las claves environment/env_file en docker-compose.yml, que fijan variables al estilo process.env dentro del contenedor.", is_correct: true }, { text: "Environment variables must be baked into the image at build time and cannot be overridden.", text_es: "Las variables de entorno deben incrustarse en la imagen en tiempo de build y no se pueden sobrescribir.", is_correct: false }, { text: "Only .env files placed inside the container's filesystem are supported.", text_es: "Solo se admiten archivos .env colocados dentro del sistema de archivos del contenedor.", is_correct: false }],
  "Docker healthcheck": [{ text: "It defines a command Docker periodically runs inside the container to determine if it's still healthy, exposing a status (healthy/unhealthy) that orchestration tools can act on.", text_es: "Define un comando que Docker ejecuta periódicamente dentro del contenedor para determinar si sigue sano, exponiendo un estado (healthy/unhealthy) sobre el que las herramientas de orquestación pueden actuar.", is_correct: true }, { text: "It automatically restarts the container every time it receives traffic.", text_es: "Reinicia automáticamente el contenedor cada vez que recibe tráfico.", is_correct: false }, { text: "It checks the health of the Docker daemon on the host, not the container.", text_es: "Comprueba el estado del daemon de Docker en el host, no del contenedor.", is_correct: false }],
  "Alpine vs full base images": [{ text: "Alpine images are much smaller (using musl libc and busybox), reducing image size and attack surface, though they can occasionally cause compatibility issues with native dependencies built against glibc.", text_es: "Las imágenes Alpine son mucho más pequeñas (usan musl libc y busybox), reduciendo el tamaño de la imagen y la superficie de ataque, aunque a veces pueden causar problemas de compatibilidad con dependencias nativas compiladas contra glibc.", is_correct: true }, { text: "Alpine images run code faster because they use a different CPU architecture.", text_es: "Las imágenes Alpine ejecutan el código más rápido porque usan una arquitectura de CPU distinta.", is_correct: false }, { text: "Alpine is only usable for Node.js images, not other languages.", text_es: "Alpine solo se puede usar en imágenes de Node.js, no en otros lenguajes.", is_correct: false }],
  "Docker Hub vs private registry": [{ text: "When images contain proprietary code or must stay within an organization's network/compliance boundary, a private registry (e.g. AWS ECR, GitHub Container Registry) controls who can pull them.", text_es: "Cuando las imágenes contienen código propietario o deben permanecer dentro del perímetro de red/cumplimiento de una organización, un registro privado (p. ej. AWS ECR, GitHub Container Registry) controla quién puede descargarlas.", is_correct: true }, { text: "Private registries are required for every Docker image, public or not.", text_es: "Los registros privados son obligatorios para toda imagen Docker, sea pública o no.", is_correct: false }, { text: "Docker Hub cannot host private (non-public) repositories at all.", text_es: "Docker Hub no puede alojar en absoluto repositorios privados (no públicos).", is_correct: false }],
  "Docker build context": [{ text: "It's the set of files (the specified directory and its contents) sent to the Docker daemon, which COPY/ADD instructions can reference — a large or unfiltered context slows the build.", text_es: "Es el conjunto de archivos (el directorio indicado y su contenido) que se envía al daemon de Docker, al que pueden referirse las instrucciones COPY/ADD; un contexto grande o sin filtrar ralentiza el build.", is_correct: true }, { text: "It refers only to the environment variables passed at build time.", text_es: "Se refiere solo a las variables de entorno pasadas en tiempo de build.", is_correct: false }, { text: "It's the network context that determines which registries the build can reach.", text_es: "Es el contexto de red que determina a qué registros puede acceder el build.", is_correct: false }],
  "Named vs anonymous volumes": [{ text: "A named volume has an explicit, reusable identifier that persists and can be reattached across containers; an anonymous volume gets a random ID and is harder to reference again, though Docker still manages its lifecycle.", text_es: "Un volumen con nombre tiene un identificador explícito y reutilizable que persiste y se puede volver a asociar a otros contenedores; uno anónimo recibe un ID aleatorio y es más difícil de referenciar después, aunque Docker sigue gestionando su ciclo de vida.", is_correct: true }, { text: "Anonymous volumes are always deleted immediately when the container stops.", text_es: "Los volúmenes anónimos siempre se eliminan de inmediato al detener el contenedor.", is_correct: false }, { text: "Named volumes can only be used with docker-compose, never plain docker run.", text_es: "Los volúmenes con nombre solo se pueden usar con docker-compose, nunca con docker run a secas.", is_correct: false }],
  "Restart policies": [{ text: "They tell the Docker daemon whether and when to automatically restart a stopped container — useful for keeping long-running services up after crashes or a host reboot.", text_es: "Le indican al daemon de Docker si debe reiniciar automáticamente un contenedor detenido y cuándo hacerlo; útil para mantener en marcha servicios de larga duración tras un fallo o un reinicio del host.", is_correct: true }, { text: "They control how many CPU cores a container can restart with.", text_es: "Controlan con cuántos núcleos de CPU puede reiniciarse un contenedor.", is_correct: false }, { text: "They determine how often the container's image is rebuilt.", text_es: "Determinan con qué frecuencia se reconstruye la imagen del contenedor.", is_correct: false }],
  "depends_on limitations": [{ text: "By default it only controls startup order (starting a dependency's container before the dependent one) — it does NOT wait for the dependency to be truly ready; use a healthcheck + condition: service_healthy for that.", text_es: "Por defecto solo controla el orden de arranque (inicia el contenedor de la dependencia antes que el dependiente); NO espera a que la dependencia esté realmente lista; para eso hace falta un healthcheck + condition: service_healthy.", is_correct: true }, { text: "It guarantees the dependency service has finished initializing before the dependent starts.", text_es: "Garantiza que el servicio dependencia ha terminado de inicializarse antes de que arranque el dependiente.", is_correct: false }, { text: "It automatically retries the dependent service until the dependency responds.", text_es: "Reintenta automáticamente el servicio dependiente hasta que la dependencia responde.", is_correct: false }],
  "Reducing image size": [{ text: "Use a minimal base image (like Alpine), multi-stage builds to drop build-only tools, combine RUN instructions to reduce layers, and avoid copying unnecessary files (via .dockerignore).", text_es: "Usar una imagen base mínima (como Alpine), builds multi-etapa para descartar herramientas que solo hacen falta en el build, combinar instrucciones RUN para reducir capas, y evitar copiar archivos innecesarios (mediante .dockerignore).", is_correct: true }, { text: "Increasing the number of RUN instructions always reduces the final image size.", text_es: "Aumentar el número de instrucciones RUN siempre reduce el tamaño final de la imagen.", is_correct: false }, { text: "Image size cannot be reduced once a base image has been chosen.", text_es: "El tamaño de la imagen no se puede reducir una vez elegida la imagen base.", is_correct: false }],
  "Docker vs Kubernetes": [{ text: "Docker builds and runs individual containers/images; Kubernetes is an orchestration platform that schedules, scales, and manages many containers (potentially from different runtimes) across a cluster of machines.", text_es: "Docker construye y ejecuta contenedores/imágenes individuales; Kubernetes es una plataforma de orquestación que programa, escala y gestiona muchos contenedores (potencialmente de distintos runtimes) a través de un clúster de máquinas.", is_correct: true }, { text: "Kubernetes is a newer replacement for the Dockerfile format.", text_es: "Kubernetes es un reemplazo más moderno del formato Dockerfile.", is_correct: false }, { text: "Docker and Kubernetes are competing, mutually exclusive alternatives that can never be used together.", text_es: "Docker y Kubernetes son alternativas competidoras y mutuamente excluyentes que nunca se pueden usar juntas.", is_correct: false }],
  "The box model": [{ text: "Content, padding, border, and margin.", text_es: "Contenido, padding, border y margin.", is_correct: true }, { text: "Content, margin, border, and padding.", text_es: "Contenido, margin, border y padding.", is_correct: false }, { text: "Border, content, margin, and padding.", text_es: "Border, contenido, margin y padding.", is_correct: false }],
  "position property values": [{ text: "relative positions an element relative to its own normal position; absolute positions it relative to its nearest positioned ancestor; fixed positions it relative to the viewport, staying in place when scrolling.", text_es: "relative posiciona un elemento respecto a su propia posición normal; absolute lo posiciona respecto a su ancestro posicionado más cercano; fixed lo posiciona respecto al viewport, quedándose fijo al hacer scroll.", is_correct: true }, { text: "All three values behave identically except for their default z-index.", text_es: "Los tres valores se comportan igual salvo por su z-index por defecto.", is_correct: false }, { text: "fixed positions an element relative to its parent, absolute relative to the viewport.", text_es: "fixed posiciona un elemento respecto a su padre, absolute respecto al viewport.", is_correct: false }],
  "z-index and stacking context": [{ text: "z-index only affects positioned elements (position other than static) and is evaluated within a stacking context — a higher z-index in one context can still render below a lower z-index in a different, higher-level stacking context.", text_es: "z-index solo afecta a elementos posicionados (position distinto de static) y se evalúa dentro de un contexto de apilamiento; un z-index más alto en un contexto puede seguir renderizándose por debajo de uno más bajo en otro contexto de nivel superior.", is_correct: true }, { text: "z-index works on every element regardless of its position value.", text_es: "z-index funciona en cualquier elemento sin importar su valor de position.", is_correct: false }, { text: "z-index is a global value compared across the entire page with no notion of context.", text_es: "z-index es un valor global que se compara en toda la página sin noción de contexto.", is_correct: false }],
  "CSS custom properties": [{ text: "Defined with --name: value (often on :root) and read with var(--name), they let you reuse and dynamically update values across a stylesheet, including via JavaScript.", text_es: "Se definen con --nombre: valor (a menudo en :root) y se leen con var(--nombre); permiten reutilizar y actualizar valores dinámicamente en una hoja de estilos, incluso desde JavaScript.", is_correct: true }, { text: "They are compiled away at build time and cannot be changed at runtime.", text_es: "Desaparecen al compilar y no se pueden cambiar en tiempo de ejecución.", is_correct: false }, { text: "They can only store color values, not other CSS value types.", text_es: "Solo pueden almacenar valores de color, no otros tipos de valor CSS.", is_correct: false }],
  "Media queries": [{ text: "A conditional CSS block (e.g. @media (max-width: 768px)) that applies styles only when the specified conditions (like viewport width) are met — the basis of responsive design.", text_es: "Un bloque CSS condicional (p. ej. @media (max-width: 768px)) que aplica estilos solo cuando se cumplen las condiciones indicadas (como el ancho del viewport); la base del diseño responsive.", is_correct: true }, { text: "A query language for fetching data from a CSS-in-JS backend.", text_es: "Un lenguaje de consulta para traer datos de un backend CSS-in-JS.", is_correct: false }, { text: "A way to detect which fonts are installed on the user's device.", text_es: "Una forma de detectar qué fuentes tiene instaladas el dispositivo del usuario.", is_correct: false }],
  "rem vs em": [{ text: "rem is always relative to the root (html) element's font size; em is relative to the font size of the current element (or its parent for some properties), so em values can compound in nested elements.", text_es: "rem siempre es relativo al tamaño de fuente del elemento raíz (html); em es relativo al tamaño de fuente del elemento actual (o de su padre en algunas propiedades), así que los valores em se pueden ir acumulando en elementos anidados.", is_correct: true }, { text: "rem and em are identical; rem is just newer syntax.", text_es: "rem y em son idénticos; rem es solo una sintaxis más nueva.", is_correct: false }, { text: "em is relative to the viewport width, rem is relative to the viewport height.", text_es: "em es relativo al ancho del viewport, rem es relativo a la altura del viewport.", is_correct: false }],
  "BEM naming convention": [{ text: "It gives class names a predictable structure (block__element--modifier) to avoid specificity conflicts and make relationships between markup and styles explicit in large codebases.", text_es: "Da a los nombres de clase una estructura predecible (block__element--modifier) para evitar conflictos de especificidad y hacer explícitas las relaciones entre el markup y los estilos en bases de código grandes.", is_correct: true }, { text: "BEM is a CSS preprocessor like Sass, converting variables into static values.", text_es: "BEM es un preprocesador CSS como Sass, que convierte variables en valores estáticos.", is_correct: false }, { text: "BEM automatically minifies and compresses class names for production.", text_es: "BEM minifica y comprime automáticamente los nombres de clase para producción.", is_correct: false }],
  "Grid template areas": [{ text: "It lets you name regions of a grid layout visually (as a string map) and place items into them with grid-area, making complex layouts more readable than counting rows/columns.", text_es: "Permite nombrar visualmente las regiones de un layout de grid (como un mapa de strings) y colocar elementos en ellas con grid-area, haciendo que los layouts complejos sean más legibles que contar filas/columnas.", is_correct: true }, { text: "It's used to define animation keyframes for grid items.", text_es: "Se usa para definir los keyframes de animación de los elementos del grid.", is_correct: false }, { text: "It automatically generates a grid layout from an array of JSON data.", text_es: "Genera automáticamente un layout de grid a partir de un array de datos JSON.", is_correct: false }],
  "Pseudo-classes vs pseudo-elements": [{ text: "A pseudo-class (single colon, e.g. :hover) selects an element in a particular state; a pseudo-element (double colon, e.g. ::before) targets a sub-part of an element that doesn't exist as a separate DOM node.", text_es: "Una pseudo-clase (un solo dos puntos, p. ej. :hover) selecciona un elemento en un estado concreto; un pseudo-elemento (doble dos puntos, p. ej. ::before) apunta a una subparte de un elemento que no existe como nodo del DOM independiente.", is_correct: true }, { text: "Pseudo-elements select element states; pseudo-classes create new DOM nodes.", text_es: "Los pseudo-elementos seleccionan estados de un elemento; las pseudo-clases crean nuevos nodos del DOM.", is_correct: false }, { text: "They are the same feature, and the number of colons has no meaning.", text_es: "Son la misma funcionalidad, y el número de dos puntos no tiene ningún significado.", is_correct: false }],
  "Transitions vs animations": [{ text: "A transition smoothly interpolates a property between two states triggered by a change (like :hover); an animation uses @keyframes to define multiple steps and can run automatically, loop, and control timing independent of a state change.", text_es: "Una transición interpola suavemente una propiedad entre dos estados provocados por un cambio (como :hover); una animación usa @keyframes para definir varios pasos y puede ejecutarse automáticamente, repetirse en bucle y controlar el tiempo de forma independiente a un cambio de estado.", is_correct: true }, { text: "Transitions require JavaScript to trigger; animations run purely in CSS.", text_es: "Las transiciones necesitan JavaScript para dispararse; las animaciones se ejecutan puramente en CSS.", is_correct: false }, { text: "Animations can only run once, transitions can loop indefinitely.", text_es: "Las animaciones solo se pueden ejecutar una vez, las transiciones pueden repetirse indefinidamente.", is_correct: false }],
  "will-change property": [{ text: "It hints to the browser that a property is about to change, letting it optimize ahead of time (e.g. promoting the element to its own compositor layer) — but overusing it can hurt performance by consuming excess memory.", text_es: "Le indica al navegador que una propiedad está a punto de cambiar, permitiéndole optimizar por adelantado (p. ej. promocionando el elemento a su propia capa del compositor); pero abusar de ella puede perjudicar el rendimiento por consumir memoria de más.", is_correct: true }, { text: "It permanently disables all future changes to that CSS property.", text_es: "Desactiva de forma permanente todos los cambios futuros de esa propiedad CSS.", is_correct: false }, { text: "It forces a synchronous reflow before every animation frame.", text_es: "Fuerza un reflow síncrono antes de cada fotograma de animación.", is_correct: false }],
  "The clamp() function": [{ text: "clamp(min, preferred, max) returns a value that scales with the preferred expression (often based on viewport units) but never goes below min or above max — useful for fluid, responsive typography.", text_es: "clamp(min, preferido, max) devuelve un valor que escala según la expresión preferida (a menudo basada en unidades de viewport) pero nunca baja de min ni supera max; útil para tipografía fluida y responsive.", is_correct: true }, { text: "It rounds a value to the nearest integer.", text_es: "Redondea un valor al entero más cercano.", is_correct: false }, { text: "It restricts an element to a fixed aspect ratio.", text_es: "Restringe un elemento a una relación de aspecto fija.", is_correct: false }],
  "CSS Modules": [{ text: "They scope class names to the specific component file by generating unique class names at build time, avoiding global class name collisions common in plain CSS.", text_es: "Limitan el alcance de los nombres de clase al archivo del componente generando nombres de clase únicos en tiempo de build, evitando las colisiones globales de nombres habituales en CSS puro.", is_correct: true }, { text: "CSS Modules replace CSS entirely with a JavaScript-only styling API.", text_es: "Los CSS Modules sustituyen por completo a CSS con una API de estilos solo en JavaScript.", is_correct: false }, { text: "CSS Modules are a runtime library that must be shipped to the browser.", text_es: "Los CSS Modules son una librería en tiempo de ejecución que hay que enviar al navegador.", is_correct: false }],
  "The :root selector": [{ text: "It matches the document's root element (<html>), and since it has the highest specificity among element-level selectors and is always present, it's the conventional place to declare global custom properties.", text_es: "Coincide con el elemento raíz del documento (<html>), y como tiene la mayor especificidad entre los selectores de elemento y siempre está presente, es el lugar habitual para declarar propiedades personalizadas globales.", is_correct: true }, { text: ":root selects every top-level child of the <body> element.", text_es: ":root selecciona todos los hijos de primer nivel del elemento <body>.", is_correct: false }, { text: ":root only works inside CSS Modules, not plain stylesheets.", text_es: ":root solo funciona dentro de CSS Modules, no en hojas de estilo normales.", is_correct: false }],
  "CSS cascade layers": [{ text: "They let you explicitly control the order in which groups of styles are applied regardless of selector specificity or source order, making it easier to manage precedence between resets, frameworks, and component styles.", text_es: "Permiten controlar explícitamente el orden en que se aplican grupos de estilos, sin importar la especificidad del selector ni el orden de origen, facilitando gestionar la precedencia entre resets, frameworks y estilos de componentes.", is_correct: true }, { text: "@layer creates isolated iframes for each stylesheet.", text_es: "@layer crea iframes aislados para cada hoja de estilos.", is_correct: false }, { text: "@layer is used exclusively to define print stylesheets.", text_es: "@layer se usa exclusivamente para definir hojas de estilo de impresión.", is_correct: false }],
  "prefers-color-scheme": [{ text: "Whether the user has requested a light or dark color theme at the OS/browser level, letting a stylesheet adapt automatically with @media (prefers-color-scheme: dark).", text_es: "Si el usuario ha pedido un tema claro u oscuro a nivel de sistema operativo/navegador, permitiendo que una hoja de estilos se adapte automáticamente con @media (prefers-color-scheme: dark).", is_correct: true }, { text: "Whether the user's monitor supports more than 16 million colors.", text_es: "Si el monitor del usuario admite más de 16 millones de colores.", is_correct: false }, { text: "Whether the page is being printed in color or grayscale.", text_es: "Si la página se está imprimiendo en color o en escala de grises.", is_correct: false }],
  "Two-pointer technique": [{ text: "Using two indices that move through a data structure (often from opposite ends or at different speeds) to solve problems like finding pairs in a sorted array in O(n) instead of O(n^2).", text_es: "Usar dos índices que recorren una estructura de datos (a menudo desde extremos opuestos o a velocidades distintas) para resolver problemas como encontrar pares en un array ordenado en O(n) en vez de O(n^2).", is_correct: true }, { text: "A technique that requires two separate arrays to be sorted independently.", text_es: "Una técnica que requiere ordenar dos arrays por separado de forma independiente.", is_correct: false }, { text: "A debugging technique for tracking two variables in a debugger.", text_es: "Una técnica de depuración para seguir dos variables en un debugger.", is_correct: false }],
  "Sliding window technique": [{ text: "Maintaining a contiguous subrange (window) over an array or string that expands/contracts as you scan, avoiding recomputation from scratch — used for problems like longest substring without repeating characters.", text_es: "Mantener un subrango contiguo (ventana) sobre un array o cadena que se expande/contrae mientras se recorre, evitando recalcular desde cero; se usa en problemas como la subcadena más larga sin caracteres repetidos.", is_correct: true }, { text: "It's a UI pattern for scrolling panels, unrelated to algorithms.", text_es: "Es un patrón de UI para paneles con scroll, sin relación con algoritmos.", is_correct: false }, { text: "It requires sorting the input array first before it can be applied.", text_es: "Requiere ordenar antes el array de entrada para poder aplicarse.", is_correct: false }],
  "Tree traversal orders": [{ text: "In-order visits left, node, right (yields sorted order for a BST); pre-order visits node, left, right; post-order visits left, right, node.", text_es: "In-order visita izquierda, nodo, derecha (da orden ascendente en un BST); pre-order visita nodo, izquierda, derecha; post-order visita izquierda, derecha, nodo.", is_correct: true }, { text: "They all visit nodes in the exact same order but differ only in return type.", text_es: "Los tres visitan los nodos exactamente en el mismo orden y solo difieren en el tipo de retorno.", is_correct: false }, { text: "Pre-order is only valid for balanced trees, the others work on any tree.", text_es: "Pre-order solo es válido para árboles balanceados, los demás funcionan en cualquier árbol.", is_correct: false }],
  "BFS vs DFS": [{ text: "BFS explores a graph level by level using a queue, finding the shortest path in unweighted graphs; DFS explores as far as possible down one branch before backtracking, typically using a stack or recursion.", text_es: "BFS explora un grafo nivel a nivel usando una cola, encontrando el camino más corto en grafos sin peso; DFS explora lo más lejos posible por una rama antes de retroceder, normalmente usando una pila o recursividad.", is_correct: true }, { text: "BFS uses recursion and DFS uses a queue.", text_es: "BFS usa recursividad y DFS usa una cola.", is_correct: false }, { text: "BFS and DFS are only applicable to trees, never general graphs.", text_es: "BFS y DFS solo se aplican a árboles, nunca a grafos generales.", is_correct: false }],
  "Merge sort": [{ text: "It recursively splits the array in half until single elements remain, then merges sorted halves back together; this runs in O(n log n) time in all cases and is stable.", text_es: "Divide recursivamente el array a la mitad hasta quedarse con elementos individuales, y luego fusiona las mitades ordenadas; se ejecuta en O(n log n) en todos los casos y es estable.", is_correct: true }, { text: "It repeatedly swaps adjacent out-of-order elements until the array is sorted.", text_es: "Va intercambiando repetidamente elementos adyacentes desordenados hasta ordenar el array.", is_correct: false }, { text: "It picks a pivot and partitions elements around it, like quicksort.", text_es: "Elige un pivote y particiona los elementos a su alrededor, como quicksort.", is_correct: false }],
  "Quicksort": [{ text: "It picks a pivot, partitions elements into those less than and greater than the pivot, and recursively sorts each partition; average case is O(n log n), but worst case (e.g. an already-sorted array with a poor pivot choice) is O(n^2).", text_es: "Elige un pivote, reparte los elementos entre los menores y mayores que el pivote, y ordena cada partición recursivamente; el caso medio es O(n log n), pero el peor caso (p. ej. un array ya ordenado con una mala elección de pivote) es O(n^2).", is_correct: true }, { text: "Quicksort's worst case is always O(n log n), same as its average case.", text_es: "El peor caso de quicksort siempre es O(n log n), igual que su caso medio.", is_correct: false }, { text: "Quicksort merges two pre-sorted halves, like merge sort.", text_es: "Quicksort fusiona dos mitades previamente ordenadas, como merge sort.", is_correct: false }],
  "Hash collisions": [{ text: "Common strategies are chaining (each slot holds a list of entries) and open addressing (probing for the next free slot), both letting multiple keys coexist despite a collision.", text_es: "Las estrategias habituales son el encadenamiento (cada slot contiene una lista de entradas) y el direccionamiento abierto (buscar el siguiente slot libre), que permiten que varias claves coexistan a pesar de la colisión.", is_correct: true }, { text: "Hash tables reject the second key and the insertion silently fails.", text_es: "Las tablas hash rechazan la segunda clave y la inserción falla en silencio.", is_correct: false }, { text: "Collisions can never happen because hash functions guarantee unique outputs.", text_es: "Las colisiones nunca pueden ocurrir porque las funciones hash garantizan salidas únicas.", is_correct: false }],
  "Dynamic programming basics": [{ text: "Optimal substructure (the optimal solution can be built from optimal solutions to subproblems) and overlapping subproblems (the same subproblems recur, so caching/memoizing their results avoids redundant work).", text_es: "Subestructura óptima (la solución óptima se puede construir a partir de soluciones óptimas de subproblemas) y subproblemas solapados (los mismos subproblemas se repiten, así que cachear/memoizar sus resultados evita trabajo redundante).", is_correct: true }, { text: "The input must already be sorted and the problem must be a graph problem.", text_es: "La entrada debe estar ya ordenada y el problema debe ser un problema de grafos.", is_correct: false }, { text: "The problem must have exactly one valid solution with no alternatives.", text_es: "El problema debe tener exactamente una solución válida, sin alternativas.", is_correct: false }],
  "Recursion vs iteration": [{ text: "Recursion can be more readable for naturally recursive problems (like tree traversal) but risks stack overflow and extra call-stack overhead; iteration avoids that overhead but can be less intuitive to express.", text_es: "La recursividad puede ser más legible en problemas naturalmente recursivos (como recorrer un árbol) pero arriesga un stack overflow y sobrecarga extra de la pila de llamadas; la iteración evita esa sobrecarga pero puede ser menos intuitiva de expresar.", is_correct: true }, { text: "Recursive solutions always run faster than iterative ones.", text_es: "Las soluciones recursivas siempre se ejecutan más rápido que las iterativas.", is_correct: false }, { text: "Iterative solutions cannot solve any problem that recursion can solve.", text_es: "Las soluciones iterativas no pueden resolver ningún problema que la recursividad pueda resolver.", is_correct: false }],
  "Array vs linked list complexity": [{ text: "Arrays offer O(1) indexed access but O(n) insertion/deletion in the middle (due to shifting); linked lists offer O(1) insertion/deletion once you have a reference to the node but O(n) access by index.", text_es: "Los arrays ofrecen acceso indexado en O(1) pero inserción/borrado en el medio en O(n) (por el desplazamiento); las listas enlazadas ofrecen inserción/borrado en O(1) una vez que tienes referencia al nodo, pero acceso por índice en O(n).", is_correct: true }, { text: "Arrays and linked lists have identical time complexity for every operation.", text_es: "Los arrays y las listas enlazadas tienen la misma complejidad temporal en todas las operaciones.", is_correct: false }, { text: "Linked lists always outperform arrays for every use case.", text_es: "Las listas enlazadas siempre rinden mejor que los arrays en cualquier caso de uso.", is_correct: false }],
  "Find the missing number": [{ text: "Compute the expected sum of 1..n using the formula n*(n+1)/2, subtract the actual sum of the array — the difference is the missing number, in O(n) time and O(1) space.", text_es: "Calcula la suma esperada de 1..n con la fórmula n*(n+1)/2, réstale la suma real del array; la diferencia es el número que falta, en O(n) de tiempo y O(1) de espacio.", is_correct: true }, { text: "You must sort the array first, which takes O(n log n) at minimum.", text_es: "Hay que ordenar antes el array, lo que cuesta como mínimo O(n log n).", is_correct: false }, { text: "It's only possible by checking every number from 1 to n against the array, in O(n^2).", text_es: "Solo es posible comprobando cada número de 1 a n contra el array, en O(n^2).", is_correct: false }],
  "Valid parentheses": [{ text: "Push opening brackets onto a stack; on a closing bracket, check it matches the top of the stack (popping it) — the string is valid if the stack ends empty.", text_es: "Apila los corchetes de apertura en una pila; al encontrar uno de cierre, comprueba que coincide con el que hay en la cima (y lo saca); la cadena es válida si la pila termina vacía.", is_correct: true }, { text: "Count the total number of opening and closing brackets and check they're equal.", text_es: "Contar el número total de corchetes de apertura y cierre y comprobar que son iguales.", is_correct: false }, { text: "Reverse the string and check it reads the same forwards and backwards.", text_es: "Invertir la cadena y comprobar que se lee igual hacia delante y hacia atrás.", is_correct: false }],
  "Binary search tree properties": [{ text: "For every node, all values in its left subtree must be smaller and all values in its right subtree must be larger than the node's own value.", text_es: "Para cada nodo, todos los valores de su subárbol izquierdo deben ser menores y todos los de su subárbol derecho deben ser mayores que el valor del propio nodo.", is_correct: true }, { text: "Every node must have exactly two children, or the tree is invalid.", text_es: "Cada nodo debe tener exactamente dos hijos, o el árbol no es válido.", is_correct: false }, { text: "The tree must always be perfectly balanced to be considered a valid BST.", text_es: "El árbol siempre debe estar perfectamente balanceado para considerarse un BST válido.", is_correct: false }],
  "Graph representations": [{ text: "An adjacency list uses O(V+E) space and is efficient for sparse graphs; an adjacency matrix uses O(V^2) space but gives O(1) edge-existence checks, better suited to dense graphs.", text_es: "Una lista de adyacencia usa O(V+E) de espacio y es eficiente para grafos dispersos; una matriz de adyacencia usa O(V^2) de espacio pero permite comprobar si existe una arista en O(1), más adecuada para grafos densos.", is_correct: true }, { text: "Adjacency matrices always use less memory than adjacency lists.", text_es: "Las matrices de adyacencia siempre usan menos memoria que las listas de adyacencia.", is_correct: false }, { text: "Adjacency lists cannot represent directed graphs, only undirected ones.", text_es: "Las listas de adyacencia no pueden representar grafos dirigidos, solo no dirigidos.", is_correct: false }],
  "Kadane's algorithm": [{ text: "It finds the maximum sum of a contiguous subarray in O(n) time by tracking the best sum ending at the current position, resetting to the current element whenever the running sum would go negative.", text_es: "Encuentra la suma máxima de un subarray contiguo en O(n) llevando la mejor suma que termina en la posición actual, reiniciándola al elemento actual cada vez que la suma acumulada se volvería negativa.", is_correct: true }, { text: "It finds the shortest path between two nodes in a weighted graph.", text_es: "Encuentra el camino más corto entre dos nodos en un grafo con pesos.", is_correct: false }, { text: "It sorts an array in O(n) time using bucket sort.", text_es: "Ordena un array en O(n) usando bucket sort.", is_correct: false }],
  "Load balancer algorithms": [{ text: "Round robin cycles through servers evenly; least connections routes to the server with fewest active connections; consistent hashing routes based on a key so the same client tends to hit the same server.", text_es: "Round robin va rotando por los servidores de forma equitativa; least connections dirige al servidor con menos conexiones activas; consistent hashing enruta según una clave, de forma que el mismo cliente tiende a caer en el mismo servidor.", is_correct: true }, { text: "Load balancers only support randomly picking a server with no other strategy.", text_es: "Los balanceadores de carga solo admiten elegir un servidor al azar, sin otra estrategia.", is_correct: false }, { text: "All load balancing algorithms guarantee perfectly equal CPU usage across servers.", text_es: "Todos los algoritmos de balanceo garantizan un uso de CPU perfectamente igual entre servidores.", is_correct: false }],
  "Database sharding": [{ text: "Splitting a large dataset across multiple database instances (shards), typically by a shard key, to scale writes and storage horizontally — it introduces challenges like cross-shard queries/joins and rebalancing.", text_es: "Dividir un conjunto de datos grande entre varias instancias de base de datos (shards), normalmente según una shard key, para escalar escrituras y almacenamiento horizontalmente; introduce desafíos como consultas/joins entre shards y el rebalanceo.", is_correct: true }, { text: "Sharding means creating read replicas of the exact same data on every server.", text_es: "El sharding consiste en crear réplicas de lectura con exactamente los mismos datos en cada servidor.", is_correct: false }, { text: "Sharding is a caching technique that has nothing to do with data storage.", text_es: "El sharding es una técnica de caché que no tiene nada que ver con el almacenamiento de datos.", is_correct: false }],
  "Master-replica replication": [{ text: "Synchronous replication waits for the replica to confirm the write before acknowledging success (strong consistency, higher latency); asynchronous replication acknowledges immediately and replicates in the background (lower latency, risk of data loss on failover).", text_es: "La replicación síncrona espera a que la réplica confirme la escritura antes de dar por buena la operación (consistencia fuerte, más latencia); la asíncrona confirma de inmediato y replica en segundo plano (menor latencia, riesgo de pérdida de datos en un failover).", is_correct: true }, { text: "Synchronous replication is always slower and provides no consistency guarantee.", text_es: "La replicación síncrona siempre es más lenta y no ofrece ninguna garantía de consistencia.", is_correct: false }, { text: "Asynchronous replication guarantees zero data loss during a failover.", text_es: "La replicación asíncrona garantiza cero pérdida de datos durante un failover.", is_correct: false }],
  "Message queues": [{ text: "To decouple producers from consumers, buffer bursts of traffic, enable asynchronous processing, and allow consumers to fail or scale independently without losing messages.", text_es: "Para desacoplar a los productores de los consumidores, absorber picos de tráfico, permitir el procesamiento asíncrono, y que los consumidores puedan fallar o escalar de forma independiente sin perder mensajes.", is_correct: true }, { text: "Message queues are only useful for sending emails, not general service communication.", text_es: "Las colas de mensajes solo sirven para enviar emails, no para la comunicación general entre servicios.", is_correct: false }, { text: "A message queue guarantees messages are always processed in under 1ms.", text_es: "Una cola de mensajes garantiza que los mensajes siempre se procesan en menos de 1ms.", is_correct: false }],
  "Idempotency in APIs": [{ text: "An idempotent endpoint produces the same result no matter how many times the same request is retried (e.g. using an idempotency key), preventing duplicate side effects like double-charging on network retries.", text_es: "Un endpoint idempotente produce el mismo resultado sin importar cuántas veces se reintente la misma petición (p. ej. usando una idempotency key), evitando efectos secundarios duplicados como cobrar dos veces por un reintento de red.", is_correct: true }, { text: "Idempotency means the endpoint can never be called more than once, ever.", text_es: "La idempotencia significa que el endpoint nunca se puede llamar más de una vez, jamás.", is_correct: false }, { text: "Idempotency only matters for GET requests, never for POST or PUT.", text_es: "La idempotencia solo importa en peticiones GET, nunca en POST o PUT.", is_correct: false }],
  "API Gateway pattern": [{ text: "It's a single entry point that routes client requests to the right backend service, and commonly handles cross-cutting concerns like authentication, rate limiting, and request/response transformation.", text_es: "Es un único punto de entrada que enruta las peticiones del cliente al servicio backend adecuado, y suele encargarse de aspectos transversales como autenticación, rate limiting y transformación de petición/respuesta.", is_correct: true }, { text: "It replaces the need for individual services to have their own databases.", text_es: "Elimina la necesidad de que cada servicio tenga su propia base de datos.", is_correct: false }, { text: "It's used only for serving static frontend assets, not API traffic.", text_es: "Solo se usa para servir assets estáticos del frontend, no tráfico de API.", is_correct: false }],
  "Microservices vs monolith": [{ text: "Microservices allow independent deployment and scaling of services at the cost of operational complexity (network calls, distributed data, observability); a monolith is simpler to develop and deploy but scales and deploys as one unit.", text_es: "Los microservicios permiten desplegar y escalar servicios de forma independiente a costa de complejidad operativa (llamadas de red, datos distribuidos, observabilidad); un monolito es más sencillo de desarrollar y desplegar pero escala y se despliega como una sola unidad.", is_correct: true }, { text: "Microservices always have better performance than a monolith for every workload.", text_es: "Los microservicios siempre tienen mejor rendimiento que un monolito en cualquier carga de trabajo.", is_correct: false }, { text: "A monolith cannot be scaled horizontally under any circumstances.", text_es: "Un monolito no se puede escalar horizontalmente bajo ninguna circunstancia.", is_correct: false }],
  "Consistent hashing": [{ text: "When servers are added or removed, consistent hashing minimizes the number of keys that need to be remapped (only a fraction, not all of them), unlike simple modulo hashing which reshuffles almost everything.", text_es: "Cuando se añaden o quitan servidores, el consistent hashing minimiza el número de claves que hay que remapear (solo una fracción, no todas), a diferencia del hashing por módulo simple, que reordena casi todo.", is_correct: true }, { text: "It guarantees every server holds exactly the same number of keys at all times.", text_es: "Garantiza que cada servidor tenga siempre exactamente el mismo número de claves.", is_correct: false }, { text: "It's a technique for compressing hash values to save memory.", text_es: "Es una técnica para comprimir valores hash y ahorrar memoria.", is_correct: false }],
  "CDN purpose": [{ text: "A Content Delivery Network caches and serves content from servers geographically close to users, reducing latency and offloading traffic from the origin server.", text_es: "Una red de distribución de contenidos (CDN) cachea y sirve contenido desde servidores geográficamente cercanos a los usuarios, reduciendo la latencia y aliviando el tráfico del servidor de origen.", is_correct: true }, { text: "A CDN is a database that replicates data for stronger consistency guarantees.", text_es: "Un CDN es una base de datos que replica datos para dar garantías de consistencia más fuertes.", is_correct: false }, { text: "A CDN only works for video content, not images, scripts, or HTML.", text_es: "Un CDN solo funciona con contenido de vídeo, no con imágenes, scripts o HTML.", is_correct: false }],
  "Designing a notification system": [{ text: "A queue to buffer and decouple notification events, worker services to fan out to different channels (push, email, SMS), user preference/subscription storage, and retry/dead-letter handling for failed deliveries.", text_es: "Una cola para amortiguar y desacoplar los eventos de notificación, servicios worker para distribuir hacia distintos canales (push, email, SMS), almacenamiento de preferencias/suscripciones de usuario, y manejo de reintentos/dead-letter para los envíos fallidos.", is_correct: true }, { text: "A single synchronous HTTP call made directly from the application to every user's device.", text_es: "Una única llamada HTTP síncrona hecha directamente desde la aplicación a cada dispositivo de usuario.", is_correct: false }, { text: "Notifications should always be stored only in the client app's local storage.", text_es: "Las notificaciones siempre deberían guardarse solo en el almacenamiento local de la app del cliente.", is_correct: false }],
  "Designing a news feed": [{ text: "Fan-out on write pre-computes and pushes new posts into each follower's feed immediately (fast reads, expensive for celebrities with huge followings); fan-out on read computes the feed at request time by pulling from followed users (cheaper writes, slower reads).", text_es: "El fan-out en escritura precalcula y empuja las publicaciones nuevas al feed de cada seguidor de inmediato (lecturas rápidas, costoso para cuentas con muchísimos seguidores); el fan-out en lectura calcula el feed en el momento de la petición trayendo datos de los usuarios seguidos (escrituras más baratas, lecturas más lentas).", is_correct: true }, { text: "News feeds must always be computed entirely at read time with no caching.", text_es: "Los feeds de noticias siempre deben calcularse por completo en el momento de la lectura, sin caché.", is_correct: false }, { text: "Fan-out only refers to spreading traffic across multiple load balancers.", text_es: "Fan-out solo se refiere a repartir el tráfico entre varios balanceadores de carga.", is_correct: false }],
  "Circuit breaker pattern": [{ text: "It stops a service from repeatedly calling a failing dependency by 'opening' after a failure threshold, failing fast instead of piling up timeouts, and periodically testing if the dependency has recovered.", text_es: "Evita que un servicio siga llamando repetidamente a una dependencia que falla, 'abriéndose' tras superar un umbral de fallos, fallando rápido en lugar de acumular timeouts, y probando periódicamente si la dependencia se ha recuperado.", is_correct: true }, { text: "It physically disconnects a server's network cable when it detects an attack.", text_es: "Desconecta físicamente el cable de red de un servidor cuando detecta un ataque.", is_correct: false }, { text: "It's a database transaction isolation level, not a resilience pattern.", text_es: "Es un nivel de aislamiento de transacciones de base de datos, no un patrón de resiliencia.", is_correct: false }],
  "Data partitioning strategies": [{ text: "Range-based partitioning assigns contiguous key ranges to each partition (good for range queries, but risks hot spots); hash-based partitioning distributes keys more evenly via a hash function but makes range queries harder.", text_es: "El particionado por rangos asigna rangos de claves contiguos a cada partición (bueno para consultas por rango, pero con riesgo de hot spots); el particionado por hash distribuye las claves de forma más uniforme mediante una función hash pero dificulta las consultas por rango.", is_correct: true }, { text: "Range-based and hash-based partitioning always produce identical data distributions.", text_es: "El particionado por rangos y por hash siempre producen distribuciones de datos idénticas.", is_correct: false }, { text: "Partitioning strategy only affects storage cost, never query performance.", text_es: "La estrategia de particionado solo afecta al coste de almacenamiento, nunca al rendimiento de las consultas.", is_correct: false }],
  "Distributed file storage": [{ text: "Splitting large files into chunks/blocks distributed and replicated across storage nodes, a metadata service mapping files to chunk locations, and mechanisms for consistency and re-replication when nodes fail.", text_es: "Dividir los archivos grandes en fragmentos/bloques distribuidos y replicados entre nodos de almacenamiento, un servicio de metadatos que mapea los archivos a la ubicación de sus fragmentos, y mecanismos de consistencia y re-replicación cuando fallan nodos.", is_correct: true }, { text: "Storing the entire file as a single unit on one server with no chunking.", text_es: "Guardar el archivo entero como una sola unidad en un servidor, sin fragmentar.", is_correct: false }, { text: "Distributed storage requires every client to keep a full local copy of all files.", text_es: "El almacenamiento distribuido exige que cada cliente guarde una copia local completa de todos los archivos.", is_correct: false }],
  "Reverse proxy": [{ text: "A server that sits between clients and backend servers, forwarding requests to the right backend and commonly handling TLS termination, load balancing, caching, and compression.", text_es: "Un servidor que se sitúa entre los clientes y los servidores backend, reenviando las peticiones al backend correcto y encargándose habitualmente de la terminación TLS, el balanceo de carga, la caché y la compresión.", is_correct: true }, { text: "A proxy that only forwards outbound requests from internal servers to the internet.", text_es: "Un proxy que solo reenvía peticiones salientes de servidores internos hacia internet.", is_correct: false }, { text: "A reverse proxy is another name for a VPN.", text_es: "Un proxy inverso es otro nombre para una VPN.", is_correct: false }],
  "Nginx vs Apache": [{ text: "Nginx uses an event-driven, asynchronous architecture that handles many concurrent connections efficiently with low memory use; Apache traditionally uses a process/thread-per-connection model, which can use more resources under high concurrency.", text_es: "Nginx usa una arquitectura asíncrona basada en eventos que gestiona muchas conexiones concurrentes de forma eficiente con poco consumo de memoria; Apache usa tradicionalmente un modelo de proceso/hilo por conexión, que puede consumir más recursos con alta concurrencia.", is_correct: true }, { text: "Apache and Nginx are functionally identical with no architectural differences.", text_es: "Apache y Nginx son funcionalmente idénticos, sin diferencias de arquitectura.", is_correct: false }, { text: "Nginx can only serve static files and cannot proxy dynamic requests.", text_es: "Nginx solo puede servir archivos estáticos y no puede hacer proxy de peticiones dinámicas.", is_correct: false }],
  "Monitoring and observability": [{ text: "Logs (discrete event records), metrics (numeric time-series measurements), and traces (the path of a request through distributed services).", text_es: "Los logs (registros de eventos individuales), las métricas (medidas numéricas en series temporales) y las trazas (el recorrido de una petición por servicios distribuidos).", is_correct: true }, { text: "Uptime, CPU usage, and disk space are the only three pillars.", text_es: "Uptime, uso de CPU y espacio en disco son los únicos tres pilares.", is_correct: false }, { text: "Observability refers only to how visually appealing a monitoring dashboard is.", text_es: "La observabilidad solo se refiere a lo visualmente atractivo que sea un panel de monitorización.", is_correct: false }],
  "Logging best practices": [{ text: "Use structured (e.g. JSON) logs with consistent fields, include correlation/request IDs, log at appropriate levels (info/warn/error), and avoid logging sensitive data like passwords or tokens.", text_es: "Usar logs estructurados (p. ej. JSON) con campos consistentes, incluir IDs de correlación/petición, registrar en el nivel adecuado (info/warn/error), y evitar registrar datos sensibles como contraseñas o tokens.", is_correct: true }, { text: "Logging should always write directly to the console with no structure or levels.", text_es: "El logging siempre debería escribir directamente a la consola, sin estructura ni niveles.", is_correct: false }, { text: "Production systems should disable logging entirely to save disk space.", text_es: "Los sistemas de producción deberían desactivar el logging por completo para ahorrar espacio en disco.", is_correct: false }],
  "Secrets management": [{ text: "Git history is hard to fully purge and often shared broadly, so a leaked secret could remain accessible indefinitely; secrets should instead be injected via environment variables or a dedicated secrets manager (like Vault or AWS Secrets Manager).", text_es: "El historial de Git es difícil de purgar por completo y suele compartirse ampliamente, así que un secreto filtrado podría quedar accesible indefinidamente; en su lugar, los secretos deberían inyectarse mediante variables de entorno o un gestor de secretos dedicado (como Vault o AWS Secrets Manager).", is_correct: true }, { text: "Committing secrets to Git is safe as long as the repository is set to private.", text_es: "Commitear secretos en Git es seguro mientras el repositorio sea privado.", is_correct: false }, { text: "Git automatically encrypts any file matching a filename like .env.", text_es: "Git cifra automáticamente cualquier archivo con un nombre como .env.", is_correct: false }],
  "Feature flags": [{ text: "A runtime toggle that turns a feature on or off (often per user segment) without a new deploy, allowing gradual rollouts, A/B testing, and instant rollback of a problematic feature.", text_es: "Un interruptor en tiempo de ejecución que activa o desactiva una funcionalidad (a menudo por segmento de usuario) sin necesidad de un nuevo despliegue, permitiendo lanzamientos graduales, A/B testing y revertir al instante una funcionalidad problemática.", is_correct: true }, { text: "A flag set at compile time that can never be changed after deployment.", text_es: "Un flag que se fija en tiempo de compilación y que nunca se puede cambiar después del despliegue.", is_correct: false }, { text: "Feature flags are only used to mark deprecated code for deletion.", text_es: "Los feature flags solo se usan para marcar código obsoleto pendiente de eliminar.", is_correct: false }],
  "GitOps": [{ text: "Using a Git repository as the single source of truth for declarative infrastructure/application state, where an automated controller continuously reconciles the live environment to match what's committed to Git.", text_es: "Usar un repositorio Git como única fuente de verdad para el estado declarativo de la infraestructura/aplicación, donde un controlador automatizado reconcilia continuamente el entorno real con lo que hay commiteado en Git.", is_correct: true }, { text: "GitOps means every developer has direct SSH access to production servers.", text_es: "GitOps significa que todo desarrollador tiene acceso SSH directo a los servidores de producción.", is_correct: false }, { text: "GitOps is a branching strategy unrelated to deployment or infrastructure.", text_es: "GitOps es una estrategia de branching sin relación con el despliegue o la infraestructura.", is_correct: false }],
  "Immutable infrastructure": [{ text: "Instead of patching running servers in place, you build a new server/image with the change and replace the old one entirely — reducing configuration drift and making deployments more predictable and reversible.", text_es: "En lugar de parchear los servidores en marcha, se construye un servidor/imagen nueva con el cambio y se sustituye por completo la anterior, reduciendo el configuration drift y haciendo los despliegues más predecibles y reversibles.", is_correct: true }, { text: "It means production infrastructure can never be updated once it is created.", text_es: "Significa que la infraestructura de producción nunca se puede actualizar una vez creada.", is_correct: false }, { text: "It refers to infrastructure that has no version control at all.", text_es: "Se refiere a infraestructura que no tiene ningún control de versiones.", is_correct: false }],
  "Horizontal pod autoscaling": [{ text: "It periodically checks a metric (commonly CPU or memory utilization, or a custom metric) against a target threshold and adjusts the number of pod replicas up or down to try to keep the metric near that target.", text_es: "Comprueba periódicamente una métrica (habitualmente uso de CPU o memoria, o una métrica personalizada) frente a un umbral objetivo, y ajusta el número de réplicas de pods al alza o a la baja para intentar mantener la métrica cerca de ese objetivo.", is_correct: true }, { text: "It scales based purely on the time of day, with no metric involved.", text_es: "Escala basándose únicamente en la hora del día, sin ninguna métrica de por medio.", is_correct: false }, { text: "It always scales to the maximum replica count immediately after any traffic increase.", text_es: "Siempre escala al número máximo de réplicas inmediatamente después de cualquier aumento de tráfico.", is_correct: false }],
  "Liveness vs readiness probes": [{ text: "A liveness probe determines if a container is still running correctly (a failure triggers a restart); a readiness probe determines if it's ready to receive traffic (a failure removes it from the service's load balancing without restarting it).", text_es: "Una liveness probe determina si un contenedor sigue funcionando correctamente (un fallo provoca un reinicio); una readiness probe determina si está listo para recibir tráfico (un fallo lo saca del balanceo del servicio sin reiniciarlo).", is_correct: true }, { text: "They are identical checks with different names for compatibility reasons.", text_es: "Son comprobaciones idénticas con nombres distintos por motivos de compatibilidad.", is_correct: false }, { text: "A readiness probe restarts the container; a liveness probe removes it from traffic.", text_es: "Una readiness probe reinicia el contenedor; una liveness probe lo saca del tráfico.", is_correct: false }],
  "Container registries": [{ text: "It stores and versions built container images (tagged, e.g. by commit SHA) so they can be pulled reliably by staging/production environments after being built once in CI.", text_es: "Almacena y versiona las imágenes de contenedor ya construidas (etiquetadas, p. ej. por el SHA del commit) para que los entornos de staging/producción puedan descargarlas de forma fiable tras construirse una única vez en CI.", is_correct: true }, { text: "It's a database that stores application user accounts.", text_es: "Es una base de datos que almacena las cuentas de usuario de la aplicación.", is_correct: false }, { text: "It's used only to store source code, not built artifacts.", text_es: "Solo se usa para guardar código fuente, no artefactos ya construidos.", is_correct: false }],
  "Zero-downtime deployment": [{ text: "Run the new version alongside the old one (e.g. rolling update or blue-green) and only shift traffic once new instances pass health checks, draining connections from old instances gracefully instead of killing them abruptly.", text_es: "Ejecutar la nueva versión junto a la antigua (p. ej. rolling update o blue-green) y desviar el tráfico solo cuando las nuevas instancias pasan los health checks, drenando las conexiones de las instancias antiguas de forma controlada en vez de matarlas de golpe.", is_correct: true }, { text: "Zero-downtime deployment requires stopping the old version before starting the new one.", text_es: "El despliegue sin downtime requiere detener la versión antigua antes de arrancar la nueva.", is_correct: false }, { text: "It's only achievable by scheduling deployments during a maintenance window.", text_es: "Solo se puede conseguir programando los despliegues en una ventana de mantenimiento.", is_correct: false }],
  "Monitoring alerts": [{ text: "It's actionable (someone can actually do something about it), tied to a meaningful threshold or symptom (not just any anomaly), and avoids flapping/false positives that lead to alert fatigue.", text_es: "Es accionable (alguien puede realmente hacer algo al respecto), está ligada a un umbral o síntoma significativo (no a cualquier anomalía), y evita el flapping/falsos positivos que generan fatiga de alertas.", is_correct: true }, { text: "A good alert fires for every single metric fluctuation, however small.", text_es: "Una buena alerta salta ante cualquier fluctuación de una métrica, por pequeña que sea.", is_correct: false }, { text: "Alerts should never include any context about what triggered them.", text_es: "Las alertas nunca deberían incluir contexto sobre qué las disparó.", is_correct: false }],
  "Configuration management tools": [{ text: "They let you declaratively define and automatically enforce a server's configuration (packages, files, services) across many machines, avoiding manual, inconsistent, hard-to-reproduce setup steps.", text_es: "Permiten definir de forma declarativa y aplicar automáticamente la configuración de un servidor (paquetes, archivos, servicios) en muchas máquinas, evitando pasos de configuración manuales, inconsistentes y difíciles de reproducir.", is_correct: true }, { text: "They are used exclusively to manage DNS records for a domain.", text_es: "Se usan exclusivamente para gestionar los registros DNS de un dominio.", is_correct: false }, { text: "They replace the need for any container technology like Docker.", text_es: "Eliminan la necesidad de cualquier tecnología de contenedores como Docker.", is_correct: false }],
  "SLA, SLO, and SLI": [{ text: "An SLI is a measured indicator (e.g. request latency); an SLO is an internal target for that indicator (e.g. 99.9% of requests under 200ms); an SLA is an external, often contractual, commitment with consequences if unmet.", text_es: "Un SLI es un indicador medido (p. ej. la latencia de las peticiones); un SLO es un objetivo interno para ese indicador (p. ej. el 99,9% de las peticiones en menos de 200ms); un SLA es un compromiso externo, a menudo contractual, con consecuencias si no se cumple.", is_correct: true }, { text: "They are three different names for the exact same concept.", text_es: "Son tres nombres distintos para exactamente el mismo concepto.", is_correct: false }, { text: "An SLA is always stricter than the SLO it's built from.", text_es: "Un SLA siempre es más estricto que el SLO en el que se basa.", is_correct: false }],
  "Rollback strategies": [{ text: "Redeploying the previous known-good image/version (common in blue-green or with version-tagged artifacts), or using a platform's built-in rollback command that shifts traffic back to the prior release.", text_es: "Volver a desplegar la última imagen/versión que funcionaba bien (habitual en blue-green o con artefactos etiquetados por versión), o usar el comando de rollback integrado de la plataforma que devuelve el tráfico a la versión anterior.", is_correct: true }, { text: "Rollbacks require manually rewriting the application code from scratch.", text_es: "Los rollbacks exigen reescribir manualmente el código de la aplicación desde cero.", is_correct: false }, { text: "Once deployed, a release can never be reverted, only fixed forward.", text_es: "Una vez desplegada, una versión nunca se puede revertir, solo corregir hacia delante.", is_correct: false }],
  "SQL Injection prevention": [{ text: "Use parameterized queries / prepared statements (never string-concatenate user input into SQL), and validate/escape input as defense in depth.", text_es: "Usar consultas parametrizadas / prepared statements (nunca concatenar como string la entrada del usuario en el SQL), y validar/escapar la entrada como capa extra de defensa.", is_correct: true }, { text: "SQL injection is prevented automatically by using an ORM, with no other precautions needed.", text_es: "La inyección SQL se previene automáticamente usando un ORM, sin necesitar ninguna otra precaución.", is_correct: false }, { text: "It's enough to filter out only the word SELECT from user input.", text_es: "Basta con filtrar solo la palabra SELECT de la entrada del usuario.", is_correct: false }],
  "Password hashing": [{ text: "bcrypt/argon2 are deliberately slow and configurable (via a work factor/cost parameter) and include salting by design, making brute-force and rainbow-table attacks far more expensive than with a fast general-purpose hash like SHA-256.", text_es: "bcrypt/argon2 son deliberadamente lentos y configurables (mediante un parámetro de coste/work factor) e incluyen salting por diseño, haciendo mucho más costosos los ataques de fuerza bruta y rainbow tables que con un hash genérico rápido como SHA-256.", is_correct: true }, { text: "SHA-256 is actually more secure than bcrypt for storing passwords.", text_es: "SHA-256 es en realidad más seguro que bcrypt para almacenar contraseñas.", is_correct: false }, { text: "Password hashing algorithm choice has no effect on brute-force resistance.", text_es: "La elección del algoritmo de hashing no afecta en nada a la resistencia frente a la fuerza bruta.", is_correct: false }],
  "HTTPS and TLS basics": [{ text: "Encryption of data in transit (confidentiality), integrity checking (tampering detection), and authentication of the server via its certificate.", text_es: "Cifrado de los datos en tránsito (confidencialidad), comprobación de integridad (detección de manipulación), y autenticación del servidor mediante su certificado.", is_correct: true }, { text: "TLS only encrypts the request headers, never the body of the request.", text_es: "TLS solo cifra las cabeceras de la petición, nunca el cuerpo.", is_correct: false }, { text: "HTTPS guarantees the application code itself has no vulnerabilities.", text_es: "HTTPS garantiza que el propio código de la aplicación no tiene vulnerabilidades.", is_correct: false }],
  "CORS explained": [{ text: "Cross-Origin Resource Sharing is a browser mechanism that lets a server explicitly allow (via headers like Access-Control-Allow-Origin) web pages from other origins to make requests to it, relaxing the default same-origin restriction safely.", text_es: "Cross-Origin Resource Sharing es un mecanismo del navegador que permite a un servidor autorizar explícitamente (mediante cabeceras como Access-Control-Allow-Origin) que páginas de otros orígenes le hagan peticiones, relajando de forma segura la restricción same-origin por defecto.", is_correct: true }, { text: "CORS is a server-side firewall that blocks all cross-origin requests permanently.", text_es: "CORS es un firewall del lado servidor que bloquea permanentemente todas las peticiones cross-origin.", is_correct: false }, { text: "CORS encrypts requests made between different domains.", text_es: "CORS cifra las peticiones hechas entre distintos dominios.", is_correct: false }],
  "Rate limiting for security": [{ text: "By capping the number of login attempts allowed from a given account/IP within a time window, it makes it impractical for an attacker to try large numbers of password guesses quickly.", text_es: "Al limitar el número de intentos de login permitidos desde una cuenta/IP en una ventana de tiempo, hace inviable que un atacante pruebe rápidamente un gran número de contraseñas.", is_correct: true }, { text: "Rate limiting only protects against SQL injection, not brute-force attacks.", text_es: "El rate limiting solo protege contra la inyección SQL, no contra los ataques de fuerza bruta.", is_correct: false }, { text: "Rate limiting is applied exclusively to outbound requests from the server.", text_es: "El rate limiting solo se aplica a las peticiones salientes del servidor.", is_correct: false }],
  "Principle of least privilege": [{ text: "Every user, process, or service should be granted only the minimum permissions necessary to do its job, limiting the damage possible if that account or component is compromised.", text_es: "A cada usuario, proceso o servicio se le deberían conceder solo los permisos mínimos necesarios para hacer su trabajo, limitando el daño posible si esa cuenta o componente se ve comprometido.", is_correct: true }, { text: "Every account should be granted admin access by default for convenience.", text_es: "A toda cuenta se le debería dar acceso de administrador por defecto, por comodidad.", is_correct: false }, { text: "It applies only to database users, not application services or employees.", text_es: "Solo se aplica a los usuarios de base de datos, no a los servicios de la aplicación ni a los empleados.", is_correct: false }],
  "Secure cookie flags": [{ text: "HttpOnly blocks JavaScript from reading the cookie (mitigating XSS token theft); Secure ensures the cookie is only sent over HTTPS; SameSite restricts when the cookie is sent on cross-site requests (mitigating CSRF).", text_es: "HttpOnly impide que JavaScript pueda leer la cookie (mitigando el robo de tokens por XSS); Secure garantiza que la cookie solo se envíe por HTTPS; SameSite restringe cuándo se envía la cookie en peticiones cross-site (mitigando CSRF).", is_correct: true }, { text: "All three flags do the exact same thing: encrypt the cookie's value.", text_es: "Los tres flags hacen exactamente lo mismo: cifrar el valor de la cookie.", is_correct: false }, { text: "These flags are only relevant for cookies set by third-party ad networks.", text_es: "Estos flags solo son relevantes para cookies puestas por redes publicitarias de terceros.", is_correct: false }],
  "Content Security Policy": [{ text: "It restricts which sources (scripts, styles, images, etc.) a page is allowed to load content from, significantly reducing the impact of XSS by blocking execution of injected, disallowed scripts.", text_es: "Restringe desde qué orígenes (scripts, estilos, imágenes, etc.) se le permite a una página cargar contenido, reduciendo significativamente el impacto de XSS al bloquear la ejecución de scripts inyectados no permitidos.", is_correct: true }, { text: "CSP encrypts all content on the page so it cannot be viewed by attackers.", text_es: "CSP cifra todo el contenido de la página para que los atacantes no puedan verlo.", is_correct: false }, { text: "CSP is a database-level access control policy, unrelated to the browser.", text_es: "CSP es una política de control de acceso a nivel de base de datos, sin relación con el navegador.", is_correct: false }],
  "Dependency vulnerability scanning": [{ text: "To detect known vulnerabilities in third-party dependencies (and their transitive dependencies) early, since a vulnerable library can be exploited even if your own code has no bugs.", text_es: "Para detectar pronto vulnerabilidades conocidas en dependencias de terceros (y sus dependencias transitivas), ya que una librería vulnerable se puede explotar aunque tu propio código no tenga fallos.", is_correct: true }, { text: "These tools are only used to check code style, not security.", text_es: "Estas herramientas solo se usan para comprobar el estilo del código, no la seguridad.", is_correct: false }, { text: "Dependency scanning replaces the need for any other security testing.", text_es: "El escaneo de dependencias elimina la necesidad de cualquier otro testing de seguridad.", is_correct: false }],
  "Two-factor authentication": [{ text: "A second, independent proof of identity (something you have, like a one-time code from an app or SMS, or something you are, like a fingerprint), so a leaked password alone isn't enough to log in.", text_es: "Una segunda prueba de identidad independiente (algo que tienes, como un código de un solo uso de una app o SMS, o algo que eres, como una huella dactilar), de forma que una contraseña filtrada por sí sola no baste para iniciar sesión.", is_correct: true }, { text: "It requires the user to enter their password twice for confirmation.", text_es: "Exige que el usuario introduzca su contraseña dos veces para confirmarla.", is_correct: false }, { text: "It replaces passwords entirely with a single security question.", text_es: "Sustituye por completo las contraseñas por una única pregunta de seguridad.", is_correct: false }],
  "OAuth 2.0 flow": [{ text: "It lets a user grant a third-party application limited access to their resources on another service (e.g. 'Sign in with Google') without sharing their actual password with that third-party application.", text_es: "Permite que un usuario conceda a una aplicación de terceros acceso limitado a sus recursos en otro servicio (p. ej. 'Iniciar sesión con Google') sin compartir su contraseña real con esa aplicación de terceros.", is_correct: true }, { text: "OAuth 2.0 is a way to encrypt passwords before storing them in a database.", text_es: "OAuth 2.0 es una forma de cifrar contraseñas antes de guardarlas en una base de datos.", is_correct: false }, { text: "OAuth 2.0 is only used for encrypting HTTP traffic, replacing TLS.", text_es: "OAuth 2.0 solo se usa para cifrar el tráfico HTTP, sustituyendo a TLS.", is_correct: false }],
  "Clickjacking prevention": [{ text: "Send an X-Frame-Options header (or the frame-ancestors directive in CSP) to prevent the page from being embedded in a hidden iframe on an attacker's site that tricks users into clicking disguised elements.", text_es: "Enviando una cabecera X-Frame-Options (o la directiva frame-ancestors de CSP) para evitar que la página se pueda incrustar en un iframe oculto en el sitio de un atacante, que engaña a los usuarios para que hagan clic en elementos disfrazados.", is_correct: true }, { text: "Clickjacking is prevented automatically by using HTTPS.", text_es: "El clickjacking se previene automáticamente usando HTTPS.", is_correct: false }, { text: "Clickjacking can only be prevented by disabling JavaScript on the page.", text_es: "El clickjacking solo se puede prevenir desactivando JavaScript en la página.", is_correct: false }],
  "Secrets in env vars vs a vault": [{ text: "Plain env vars typically lack built-in rotation, fine-grained access auditing, and can be exposed via process listings, crash dumps, or logs, whereas a secrets manager offers rotation, access control, and audit trails.", text_es: "Las variables de entorno planas normalmente no tienen rotación integrada ni auditoría de acceso fina, y pueden quedar expuestas en listados de procesos, volcados de errores o logs, mientras que un gestor de secretos ofrece rotación, control de acceso y registro de auditoría.", is_correct: true }, { text: "Environment variables are always more secure than a secrets manager.", text_es: "Las variables de entorno siempre son más seguras que un gestor de secretos.", is_correct: false }, { text: "There is no meaningful difference between the two approaches.", text_es: "No hay ninguna diferencia relevante entre los dos enfoques.", is_correct: false }],
  "Input validation and sanitization": [{ text: "Validation checks that input conforms to expected rules (type, length, format) and rejects it if not; sanitization modifies/cleans input (e.g. stripping HTML tags) to make it safe to use even if imperfect.", text_es: "La validación comprueba que la entrada cumple unas reglas esperadas (tipo, longitud, formato) y la rechaza si no; el saneamiento modifica/limpia la entrada (p. ej. eliminando etiquetas HTML) para que se pueda usar de forma segura aunque no sea perfecta.", is_correct: true }, { text: "Validation and sanitization are two names for the exact same operation.", text_es: "Validación y saneamiento son dos nombres para exactamente la misma operación.", is_correct: false }, { text: "Only one of the two is ever necessary; using both is redundant.", text_es: "Solo hace falta uno de los dos; usar ambos es redundante.", is_correct: false }],
  "SSRF": [{ text: "It occurs when an attacker tricks a server into making unintended requests (e.g. to internal-only services or cloud metadata endpoints) by manipulating a URL the server fetches on the attacker's behalf.", text_es: "Ocurre cuando un atacante engaña a un servidor para que haga peticiones no previstas (p. ej. a servicios internos o a endpoints de metadatos de la nube) manipulando una URL que el servidor obtiene en nombre del atacante.", is_correct: true }, { text: "It's a client-side attack where a script forges requests from the victim's browser.", text_es: "Es un ataque del lado cliente en el que un script falsifica peticiones desde el navegador de la víctima.", is_correct: false }, { text: "SSRF refers to forging the Referer header to bypass CSRF protection.", text_es: "SSRF se refiere a falsificar la cabecera Referer para saltarse la protección CSRF.", is_correct: false }],
  "Security headers (helmet.js)": [{ text: "It sets a collection of security-related HTTP response headers (like CSP, X-Frame-Options, X-Content-Type-Options) with sensible defaults, reducing exposure to several common web vulnerabilities.", text_es: "Configura un conjunto de cabeceras de respuesta HTTP relacionadas con la seguridad (como CSP, X-Frame-Options, X-Content-Type-Options) con valores por defecto sensatos, reduciendo la exposición a varias vulnerabilidades web comunes.", is_correct: true }, { text: "It encrypts the entire HTTP request and response bodies automatically.", text_es: "Cifra automáticamente todo el cuerpo de las peticiones y respuestas HTTP.", is_correct: false }, { text: "It replaces the need for authentication middleware entirely.", text_es: "Elimina por completo la necesidad de un middleware de autenticación.", is_correct: false }],
  "Code coverage metrics": [{ text: "It measures how much of the code was executed by the test suite (e.g. line or branch coverage); it does NOT guarantee the tests actually assert correct behavior — code can be 'covered' but not meaningfully tested.", text_es: "Mide qué parte del código ejecutó la suite de tests (p. ej. cobertura de líneas o de ramas); NO garantiza que los tests comprueben realmente el comportamiento correcto: código puede estar 'cubierto' sin estar realmente bien testeado.", is_correct: true }, { text: "100% code coverage guarantees the application has zero bugs.", text_es: "Un 100% de cobertura de código garantiza que la aplicación no tiene ningún bug.", is_correct: false }, { text: "Code coverage measures how fast the test suite runs.", text_es: "La cobertura de código mide lo rápido que se ejecuta la suite de tests.", is_correct: false }],
  "Snapshot testing": [{ text: "It captures a serialized output (e.g. rendered component markup) and compares future runs against the stored snapshot; a common pitfall is developers blindly approving/updating snapshots without reviewing whether the change is actually correct.", text_es: "Captura una salida serializada (p. ej. el markup renderizado de un componente) y compara ejecuciones futuras contra el snapshot guardado; un error común es que los desarrolladores aprueben/actualicen snapshots a ciegas sin revisar si el cambio es realmente correcto.", is_correct: true }, { text: "Snapshot testing only works for testing database schemas.", text_es: "El snapshot testing solo sirve para testear esquemas de base de datos.", is_correct: false }, { text: "Snapshots are regenerated automatically and never need developer review.", text_es: "Los snapshots se regeneran automáticamente y nunca necesitan revisión del desarrollador.", is_correct: false }],
  "Fakes, stubs, and mocks": [{ text: "A fake is a working, simplified implementation (like an in-memory DB); a stub returns canned responses to calls; a mock additionally verifies that specific interactions (calls, arguments) actually happened.", text_es: "Un fake es una implementación funcional y simplificada (como una BD en memoria); un stub devuelve respuestas predefinidas a las llamadas; un mock además verifica que ciertas interacciones concretas (llamadas, argumentos) realmente ocurrieron.", is_correct: true }, { text: "They are interchangeable terms for the exact same testing concept.", text_es: "Son términos intercambiables para exactamente el mismo concepto de testing.", is_correct: false }, { text: "A mock is a simplified working implementation, and a fake verifies interactions.", text_es: "Un mock es una implementación funcional simplificada, y un fake verifica interacciones.", is_correct: false }],
  "Arrange-Act-Assert": [{ text: "A way to structure a test into three clear sections: set up the test's preconditions (Arrange), perform the action under test (Act), and verify the outcome (Assert).", text_es: "Una forma de estructurar un test en tres secciones claras: preparar las condiciones previas del test (Arrange), ejecutar la acción que se está probando (Act), y verificar el resultado (Assert).", is_correct: true }, { text: "It's a pattern for arranging test files alphabetically in a directory.", text_es: "Es un patrón para ordenar alfabéticamente los archivos de test en un directorio.", is_correct: false }, { text: "It requires running the Assert step before the Act step for validation.", text_es: "Exige ejecutar el paso Assert antes que el paso Act para validar.", is_correct: false }],
  "Flaky tests": [{ text: "Shared mutable state between tests, race conditions in async code, reliance on real time/network calls, or test order dependence — all sources of non-determinism the test doesn't properly control.", text_es: "Estado mutable compartido entre tests, condiciones de carrera en código asíncrono, depender de tiempo real/llamadas de red, o depender del orden de ejecución: todas fuentes de no-determinismo que el test no controla bien.", is_correct: true }, { text: "Flaky tests are always caused by a bug in the testing framework itself.", text_es: "Los tests flaky siempre los causa un fallo del propio framework de testing.", is_correct: false }, { text: "Flakiness only occurs in end-to-end tests, never in unit tests.", text_es: "La inestabilidad solo ocurre en tests end-to-end, nunca en los unitarios.", is_correct: false }],
  "Testing pyramid vs trophy": [{ text: "The pyramid emphasizes mostly unit tests with few E2E tests; the trophy (popularized for frontend testing) puts more relative weight on integration tests, arguing they give better confidence per unit of effort for many UI-heavy applications.", text_es: "La pirámide da prioridad sobre todo a los tests unitarios con pocos E2E; el trofeo (popularizado para el testing de frontend) le da más peso relativo a los tests de integración, argumentando que dan más confianza por unidad de esfuerzo en muchas aplicaciones con mucha UI.", is_correct: true }, { text: "The testing trophy removes unit tests entirely in favor of only E2E tests.", text_es: "El trofeo de testing elimina por completo los tests unitarios a favor de solo tests E2E.", is_correct: false }, { text: "They describe the exact same test distribution with different shape names.", text_es: "Describen exactamente la misma distribución de tests con nombres de forma distintos.", is_correct: false }],
  "Contract testing": [{ text: "It verifies that a service's API still matches the expectations (the 'contract') its consumers rely on, catching breaking changes early without needing full end-to-end integration tests across every service.", text_es: "Verifica que la API de un servicio sigue cumpliendo las expectativas (el 'contrato') de las que dependen sus consumidores, detectando cambios que rompen algo de forma temprana sin necesitar tests de integración end-to-end completos entre todos los servicios.", is_correct: true }, { text: "Contract testing is a legal review process for open-source license compliance.", text_es: "El contract testing es un proceso de revisión legal para cumplir licencias open-source.", is_correct: false }, { text: "It only tests that HTTP status codes are returned, ignoring payload shape.", text_es: "Solo comprueba que se devuelven los códigos de estado HTTP, ignorando la forma del payload.", is_correct: false }],
  "Load testing": [{ text: "How the system behaves under expected or peak traffic — throughput, response times, and where bottlenecks or failures start to appear as load increases.", text_es: "Cómo se comporta el sistema con tráfico esperado o de pico: el throughput, los tiempos de respuesta, y dónde empiezan a aparecer cuellos de botella o fallos al aumentar la carga.", is_correct: true }, { text: "It tests whether the UI text fits correctly on different screen sizes.", text_es: "Comprueba si el texto de la UI encaja correctamente en distintos tamaños de pantalla.", is_correct: false }, { text: "Load testing is a synonym for unit testing run in a CI pipeline.", text_es: "El load testing es un sinónimo de los tests unitarios ejecutados en un pipeline de CI.", is_correct: false }],
  "TDD red-green-refactor": [{ text: "Red: write a failing test for behavior that doesn't exist yet. Green: write the minimal code to make it pass. Refactor: clean up the code while keeping the test passing.", text_es: "Rojo: escribir un test que falla para un comportamiento que aún no existe. Verde: escribir el código mínimo para que pase. Refactor: limpiar el código manteniendo el test en verde.", is_correct: true }, { text: "Red: fix a bug. Green: deploy to production. Refactor: write documentation.", text_es: "Rojo: arreglar un bug. Verde: desplegar a producción. Refactor: escribir documentación.", is_correct: false }, { text: "The cycle has no fixed order and steps can be done in any sequence.", text_es: "El ciclo no tiene un orden fijo y los pasos se pueden hacer en cualquier secuencia.", is_correct: false }],
  "Mutation testing": [{ text: "It deliberately introduces small bugs ('mutants') into the code and checks whether the test suite catches them (kills the mutant) — measuring whether tests actually assert meaningful behavior, not just execute lines.", text_es: "Introduce deliberadamente pequeños fallos ('mutantes') en el código y comprueba si la suite de tests los detecta (mata al mutante), midiendo si los tests realmente verifican un comportamiento significativo y no solo ejecutan líneas.", is_correct: true }, { text: "It measures how many times a test suite mutates shared global state.", text_es: "Mide cuántas veces una suite de tests muta el estado global compartido.", is_correct: false }, { text: "Mutation testing only checks for typos in test file names.", text_es: "El mutation testing solo comprueba erratas en los nombres de los archivos de test.", is_correct: false }],
  "Continuous testing in CI": [{ text: "To catch regressions before they're merged, giving fast feedback to the author and preventing broken code from reaching the main branch or production.", text_es: "Para detectar regresiones antes de fusionarlas, dando feedback rápido al autor y evitando que código roto llegue a la rama principal o a producción.", is_correct: true }, { text: "CI testing is only useful for catching formatting/linting issues.", text_es: "El testing en CI solo sirve para detectar problemas de formato/linting.", is_correct: false }, { text: "Running tests in CI removes the need to ever run them locally.", text_es: "Ejecutar los tests en CI elimina la necesidad de ejecutarlos nunca en local.", is_correct: false }],
  "Property-based testing": [{ text: "Instead of asserting behavior for a handful of hand-picked inputs, it defines a general property that should hold (e.g. 'reversing a list twice returns the original') and lets the framework generate many varied, often edge-case, inputs to check it.", text_es: "En lugar de comprobar el comportamiento para un puñado de entradas elegidas a mano, define una propiedad general que debe cumplirse (p. ej. 'invertir una lista dos veces devuelve la original') y deja que el framework genere muchas entradas variadas, a menudo casos límite, para comprobarla.", is_correct: true }, { text: "Property-based testing only works on functions that return booleans.", text_es: "El property-based testing solo funciona con funciones que devuelven booleanos.", is_correct: false }, { text: "It replaces the need to write any assertions at all.", text_es: "Elimina por completo la necesidad de escribir ninguna aserción.", is_correct: false }],
  "Testing React components": [{ text: "Testing components the way a user would interact with them (querying by visible text/role, simulating clicks/typing) rather than asserting on internal implementation details like state or private methods.", text_es: "Testear los componentes tal como interactuaría con ellos un usuario (consultando por texto/rol visible, simulando clics/escritura) en lugar de comprobar detalles internos de implementación como el estado o métodos privados.", is_correct: true }, { text: "It encourages testing private component internals and state directly.", text_es: "Fomenta testear directamente los internos privados y el estado de los componentes.", is_correct: false }, { text: "It requires a real browser and cannot run in a headless test environment.", text_es: "Requiere un navegador real y no puede ejecutarse en un entorno de test headless.", is_correct: false }],
  "Visual regression testing": [{ text: "Unintended visual/styling changes (layout shifts, broken CSS, wrong colors) by comparing screenshots against a baseline, even when the underlying logic and DOM structure are functionally correct.", text_es: "Cambios visuales/de estilo no deseados (desplazamientos de layout, CSS roto, colores incorrectos) comparando capturas de pantalla contra una base de referencia, incluso cuando la lógica y la estructura del DOM son funcionalmente correctas.", is_correct: true }, { text: "It only checks that JavaScript errors don't appear in the console.", text_es: "Solo comprueba que no aparezcan errores de JavaScript en la consola.", is_correct: false }, { text: "Visual regression testing replaces the need for any functional testing.", text_es: "El testing de regresión visual elimina la necesidad de cualquier testing funcional.", is_correct: false }],
  "Smoke testing": [{ text: "A quick set of tests covering the most critical, high-level functionality (does the app start, can a user log in) run after a deploy to catch major breakage before running a fuller test suite.", text_es: "Un conjunto rápido de tests que cubre la funcionalidad de más alto nivel y crítica (¿arranca la app?, ¿puede un usuario iniciar sesión?), ejecutado tras un despliegue para detectar roturas importantes antes de lanzar una suite de tests más completa.", is_correct: true }, { text: "A smoke test is a stress test that pushes the system to its breaking point.", text_es: "Un smoke test es una prueba de estrés que lleva al sistema hasta su punto de ruptura.", is_correct: false }, { text: "Smoke tests are only run once a year during a full security audit.", text_es: "Los smoke tests solo se ejecutan una vez al año durante una auditoría de seguridad completa.", is_correct: false }],
  "Test isolation": [{ text: "Isolated tests can run in any order or in parallel, fail with a clear cause, and won't produce false passes/failures from leftover state set up by a previous test.", text_es: "Los tests aislados se pueden ejecutar en cualquier orden o en paralelo, fallan con una causa clara, y no producen falsos positivos/negativos por estado residual dejado por un test anterior.", is_correct: true }, { text: "Test isolation means tests must always run one at a time on a single core.", text_es: "El aislamiento de tests significa que siempre deben ejecutarse de uno en uno en un solo núcleo.", is_correct: false }, { text: "Isolation is only relevant for end-to-end tests, not unit tests.", text_es: "El aislamiento solo es relevante para los tests end-to-end, no para los unitarios.", is_correct: false }],
  "Lazy loading images": [{ text: "Images outside the initial viewport (e.g. via loading=\"lazy\" or an IntersectionObserver) are only fetched as the user scrolls near them, reducing initial page weight and speeding up first load.", text_es: "Las imágenes fuera del viewport inicial (p. ej. mediante loading=\"lazy\" o un IntersectionObserver) solo se cargan cuando el usuario hace scroll cerca de ellas, reduciendo el peso inicial de la página y acelerando la primera carga.", is_correct: true }, { text: "Lazy loading compresses every image on the page before it is ever requested.", text_es: "El lazy loading comprime todas las imágenes de la página antes de que se lleguen a pedir.", is_correct: false }, { text: "It loads all images in parallel immediately, just in a randomized order.", text_es: "Carga todas las imágenes en paralelo de inmediato, solo que en un orden aleatorio.", is_correct: false }],
  "Caching headers": [{ text: "Cache-Control specifies how long and under what conditions a response can be cached (by the browser or a CDN); ETag provides a version identifier the client can send back to let the server confirm a cached copy is still valid (returning 304 Not Modified) instead of resending the full response.", text_es: "Cache-Control especifica cuánto tiempo y bajo qué condiciones se puede cachear una respuesta (por el navegador o un CDN); ETag ofrece un identificador de versión que el cliente puede devolver para que el servidor confirme que la copia cacheada sigue siendo válida (devolviendo 304 Not Modified) en vez de reenviar la respuesta completa.", is_correct: true }, { text: "They control how images are compressed before being sent to the client.", text_es: "Controlan cómo se comprimen las imágenes antes de enviarse al cliente.", is_correct: false }, { text: "ETag encrypts the response body, Cache-Control encrypts the headers.", text_es: "ETag cifra el cuerpo de la respuesta, Cache-Control cifra las cabeceras.", is_correct: false }],
  "Compression (gzip/brotli)": [{ text: "It reduces the number of bytes transferred over the network for text-based assets (HTML, CSS, JS, JSON), which speeds up download time especially on slower connections, at the cost of some CPU to compress/decompress.", text_es: "Reduce el número de bytes transferidos por la red para assets de texto (HTML, CSS, JS, JSON), lo que acelera la descarga, especialmente en conexiones lentas, a costa de algo de CPU para comprimir/descomprimir.", is_correct: true }, { text: "Compression reduces the number of HTTP requests a page makes.", text_es: "La compresión reduce el número de peticiones HTTP que hace una página.", is_correct: false }, { text: "gzip and brotli only work on image files, not text-based assets.", text_es: "gzip y brotli solo funcionan con archivos de imagen, no con assets de texto.", is_correct: false }],
  "Preload vs prefetch": [{ text: "preload tells the browser to fetch a resource needed for the CURRENT page with high priority as soon as possible; prefetch fetches a resource likely needed for a FUTURE navigation, at low priority during idle time.", text_es: "preload le indica al navegador que cargue con prioridad alta y cuanto antes un recurso que hace falta en la página ACTUAL; prefetch carga con prioridad baja, en tiempos muertos, un recurso que probablemente se necesitará en una navegación FUTURA.", is_correct: true }, { text: "They are identical hints; the names are just aliases for the same behavior.", text_es: "Son pistas idénticas; los nombres son solo alias del mismo comportamiento.", is_correct: false }, { text: "prefetch is for the current page and preload is for future navigations.", text_es: "prefetch es para la página actual y preload es para navegaciones futuras.", is_correct: false }],
  "Image formats": [{ text: "They typically achieve significantly smaller file sizes at comparable visual quality through more efficient compression, reducing page weight and load time.", text_es: "Normalmente logran tamaños de archivo bastante más pequeños con una calidad visual comparable gracias a una compresión más eficiente, reduciendo el peso de la página y el tiempo de carga.", is_correct: true }, { text: "WebP and AVIF always look worse than JPEG regardless of file size.", text_es: "WebP y AVIF siempre se ven peor que JPEG sin importar el tamaño del archivo.", is_correct: false }, { text: "Modern image formats can only be used for icons, never photographs.", text_es: "Los formatos de imagen modernos solo se pueden usar para iconos, nunca para fotografías.", is_correct: false }],
  "Debouncing scroll/resize handlers": [{ text: "These events can fire dozens of times per second; running expensive work (like layout calculations) on every single event can jank the UI, so limiting how often the handler actually runs keeps things smooth.", text_es: "Estos eventos pueden dispararse decenas de veces por segundo; ejecutar trabajo costoso (como cálculos de layout) en cada evento puede provocar tirones en la UI, así que limitar la frecuencia con la que se ejecuta el handler mantiene todo fluido.", is_correct: true }, { text: "Debouncing these handlers is purely a code-style preference with no performance effect.", text_es: "Aplicar debounce a estos handlers es solo una preferencia de estilo de código sin efecto en el rendimiento.", is_correct: false }, { text: "Scroll and resize events only fire once per page, so throttling has no effect.", text_es: "Los eventos de scroll y resize solo se disparan una vez por página, así que el throttle no tiene ningún efecto.", is_correct: false }],
  "List virtualization": [{ text: "Rendering thousands of DOM nodes for a huge list is slow and memory-intensive; virtualization renders only the rows currently visible in the viewport (plus a small buffer), dramatically improving render and scroll performance.", text_es: "Renderizar miles de nodos del DOM para una lista enorme es lento y consume mucha memoria; la virtualización solo renderiza las filas visibles en el viewport (más un pequeño margen), mejorando muchísimo el rendimiento del renderizado y del scroll.", is_correct: true }, { text: "Virtualization pre-renders the entire list off-screen ahead of time.", text_es: "La virtualización pre-renderiza toda la lista fuera de pantalla por adelantado.", is_correct: false }, { text: "It only applies to images, not text-based list rows.", text_es: "Solo se aplica a imágenes, no a filas de lista con texto.", is_correct: false }],
  "Minification and bundling": [{ text: "Minification strips whitespace/comments and shortens identifiers to reduce file size; bundling combines many modules into fewer files, reducing the number of separate network requests the browser must make.", text_es: "La minificación elimina espacios en blanco/comentarios y acorta identificadores para reducir el tamaño del archivo; el bundling combina muchos módulos en menos archivos, reduciendo el número de peticiones de red distintas que debe hacer el navegador.", is_correct: true }, { text: "Minification and bundling both work exclusively on image assets.", text_es: "La minificación y el bundling solo funcionan con assets de imagen.", is_correct: false }, { text: "Bundling always increases the number of requests, which is the trade-off for minification.", text_es: "El bundling siempre aumenta el número de peticiones, lo cual es la contrapartida de la minificación.", is_correct: false }],
  "HTTP/2 multiplexing": [{ text: "It allows many requests and responses to be interleaved over a single TCP connection concurrently, avoiding the head-of-line blocking and per-domain connection limits that made HTTP/1.1 rely on techniques like domain sharding.", text_es: "Permite que muchas peticiones y respuestas se entrelacen simultáneamente sobre una única conexión TCP, evitando el head-of-line blocking y los límites de conexiones por dominio que obligaban a HTTP/1.1 a recurrir a técnicas como el domain sharding.", is_correct: true }, { text: "Multiplexing means every request opens its own dedicated TCP connection, like HTTP/1.1.", text_es: "El multiplexado significa que cada petición abre su propia conexión TCP dedicada, como en HTTP/1.1.", is_correct: false }, { text: "HTTP/2 multiplexing only applies to image requests, not scripts or stylesheets.", text_es: "El multiplexado de HTTP/2 solo se aplica a peticiones de imágenes, no a scripts u hojas de estilo.", is_correct: false }],
  "Service workers and caching": [{ text: "It runs as a network proxy in the browser, letting you cache assets and API responses with custom strategies (cache-first, network-first, stale-while-revalidate), serving them instantly on repeat visits or even without a network connection.", text_es: "Funciona como un proxy de red dentro del navegador, permitiendo cachear assets y respuestas de API con estrategias personalizadas (cache-first, network-first, stale-while-revalidate), sirviéndolos al instante en visitas repetidas o incluso sin conexión de red.", is_correct: true }, { text: "Service workers replace the need for a backend server entirely.", text_es: "Los service workers eliminan por completo la necesidad de un servidor backend.", is_correct: false }, { text: "Service workers can only cache HTML documents, not other asset types.", text_es: "Los service workers solo pueden cachear documentos HTML, no otros tipos de asset.", is_correct: false }],
  "Layout thrashing": [{ text: "Repeatedly interleaving DOM reads (like offsetHeight) and writes (like style changes) in a loop forces the browser to recalculate layout synchronously on every iteration; batching all reads first, then all writes, avoids the repeated forced reflows.", text_es: "Ir alternando repetidamente lecturas del DOM (como offsetHeight) y escrituras (como cambios de estilo) dentro de un bucle obliga al navegador a recalcular el layout de forma síncrona en cada iteración; agrupar primero todas las lecturas y luego todas las escrituras evita esos reflows forzados repetidos.", is_correct: true }, { text: "Layout thrashing is caused exclusively by using too many CSS classes.", text_es: "El layout thrashing lo causa exclusivamente usar demasiadas clases CSS.", is_correct: false }, { text: "It only happens when animations are implemented with JavaScript, never CSS.", text_es: "Solo ocurre cuando las animaciones se implementan con JavaScript, nunca con CSS.", is_correct: false }],
  "Font loading strategies": [{ text: "It controls how a web font is shown while it's still loading (e.g. swap shows fallback text immediately then swaps to the custom font), preventing invisible text (FOIT) from blocking content from being seen.", text_es: "Controla cómo se muestra una fuente web mientras todavía se está cargando (p. ej. swap muestra el texto de reserva de inmediato y luego lo cambia por la fuente personalizada), evitando que el texto invisible (FOIT) impida ver el contenido.", is_correct: true }, { text: "font-display controls the font's file size on disk.", text_es: "font-display controla el tamaño en disco del archivo de la fuente.", is_correct: false }, { text: "It only affects which font weights are available, not loading behavior.", text_es: "Solo afecta a qué pesos de fuente están disponibles, no al comportamiento de carga.", is_correct: false }],
  "Time to First Byte": [{ text: "The time between the client's request and the first byte of the server's response arriving, affected by network latency, server processing time (like slow database queries), and any redirects along the way.", text_es: "El tiempo entre la petición del cliente y la llegada del primer byte de la respuesta del servidor, afectado por la latencia de red, el tiempo de procesamiento del servidor (como consultas lentas a la base de datos) y cualquier redirección por el camino.", is_correct: true }, { text: "TTFB measures how long it takes all images on the page to finish loading.", text_es: "TTFB mide cuánto tardan en terminar de cargarse todas las imágenes de la página.", is_correct: false }, { text: "TTFB is entirely determined by the client's CPU speed, not the server.", text_es: "TTFB lo determina por completo la velocidad de CPU del cliente, no el servidor.", is_correct: false }],
  "Resource hints": [{ text: "dns-prefetch resolves a domain's DNS ahead of time; preconnect goes further and also establishes the TCP/TLS connection early — both reduce the latency of a later request to that origin by doing setup work before it's actually needed.", text_es: "dns-prefetch resuelve por adelantado el DNS de un dominio; preconnect va más allá y también establece pronto la conexión TCP/TLS; ambos reducen la latencia de una petición posterior a ese origen adelantando trabajo antes de que realmente haga falta.", is_correct: true }, { text: "They immediately download the full content of a linked page in the background.", text_es: "Descargan de inmediato en segundo plano todo el contenido de una página enlazada.", is_correct: false }, { text: "These hints only work for same-origin requests, not third-party domains.", text_es: "Estas pistas solo funcionan para peticiones del mismo origen, no para dominios de terceros.", is_correct: false }],
  "Reducing JS execution time": [{ text: "Code-split and lazy-load non-critical JS, remove unused code (tree shaking), avoid large synchronous work on the main thread (offload to Web Workers when possible), and minimize expensive re-renders in UI frameworks.", text_es: "Dividir el código y cargar de forma diferida el JS no crítico, eliminar código sin usar (tree shaking), evitar trabajo síncrono grande en el hilo principal (delegándolo a Web Workers cuando sea posible), y minimizar los re-renders costosos en los frameworks de UI.", is_correct: true }, { text: "Execution time can only be reduced by upgrading the user's hardware.", text_es: "El tiempo de ejecución solo se puede reducir mejorando el hardware del usuario.", is_correct: false }, { text: "Minification alone eliminates all JavaScript execution time on the main thread.", text_es: "La minificación por sí sola elimina todo el tiempo de ejecución de JavaScript en el hilo principal.", is_correct: false }],
  "Performance API": [{ text: "Measuring precise timing of custom events and built-in metrics (navigation timing, resource timing, Core Web Vitals like LCP/CLS) directly in the browser, enabling real-user monitoring (RUM) rather than only synthetic lab tests.", text_es: "Medir con precisión el tiempo de eventos personalizados y de métricas integradas (navigation timing, resource timing, Core Web Vitals como LCP/CLS) directamente en el navegador, permitiendo monitorización de usuarios reales (RUM) y no solo pruebas sintéticas de laboratorio.", is_correct: true }, { text: "It can only measure CPU temperature on the client's device.", text_es: "Solo puede medir la temperatura de la CPU en el dispositivo del cliente.", is_correct: false }, { text: "The Performance API requires a paid third-party service to function.", text_es: "La Performance API necesita un servicio de pago de terceros para funcionar.", is_correct: false }],
};

